} lang_spec_t;

extern const lang_spec_t langs[];
extern const size_t langs_len;

/* Build a regex string matching all extensions of the selected languages.
 * ext_index is an array of language indices; len is its length.
 * Returns a malloc'd string. */
char *make_lang_regex(const size_t *lang_indices, size_t len);

/* Returns the list of extensions for a given set of languages (NULL terminated),
