#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char *make_lang_regex(const size_t *lang_indices, size_t len) {
    size_t cap = 256, n = 0;
    char *buf = malloc(cap);
    size_t i, j;
    int first = 1;
    buf[0] = '\0';
    n += snprintf(buf + n, cap - n, "\\.(");
    for (i = 0; i < len; i++) {
        const lang_spec_t *l = &langs[lang_indices[i]];
        for (j = 0; j < MAX_EXTENSIONS && l->extensions[j]; j++) {
            size_t need = strlen(l->extensions[j]) + 2;
            while (n + need + 4 >= cap) {
                cap *= 2;
                buf = realloc(buf, cap);
            }
            if (!first) {
                buf[n++] = '|';
            }
            first = 0;
            memcpy(buf + n, l->extensions[j], strlen(l->extensions[j]));
            n += strlen(l->extensions[j]);
            buf[n] = '\0';
        }
    }
    while (n + 4 >= cap) {
        cap *= 2;
        buf = realloc(buf, cap);
    }
    buf[n++] = ')';
    buf[n++] = '$';
    buf[n] = '\0';
    return buf;
}

void print_file_types(void) {
    size_t i, j;
    printf("The following file types are supported:\n");
    for (i = 0; i < langs_len; i++) {
        printf("  --%s\n    ", langs[i].name);
        for (j = 0; j < MAX_EXTENSIONS && langs[i].extensions[j]; j++) {
            printf("  .%s", langs[i].extensions[j]);
        }
        printf("\n\n");
    }
}
