{"command":"cd /workspace/src && cat > util.c <<'EOF'
#include "ag.h"
#include <stdarg.h>
#include <ctype.h>
#include <errno.h>

cli_options opts;
ag_stats stats;
pthread_mutex_t stats_mtx = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t print_mtx = PTHREAD_MUTEX_INITIALIZER;
FILE *out_fd = NULL;

static pthread_mutex_t log_mtx = PTHREAD_MUTEX_INITIALIZER;

static void vlog(FILE *fp, const char *prefix, const char *fmt, va_list ap) {
    pthread_mutex_lock(&log_mtx);
    fprintf(fp, "%s: ", prefix);
    vfprintf(fp, fmt, ap);
    fprintf(fp, "\n");
    pthread_mutex_unlock(&log_mtx);
}

void log_debug(const char *fmt, ...) {
    va_list ap;
    if (!opts.debug) {
        return;
    }
    va_start(ap, fmt);
    vlog(stdout, "DEBUG", fmt, ap);
    va_end(ap);
}

void log_msg(const char *fmt, ...) {
    va_list ap;
    if (opts.silent) {
        return;
    }
    va_start(ap, fmt);
    vlog(stdout, "MSG", fmt, ap);
    va_end(ap);
}

void log_warn(const char *fmt, ...) {
    va_list ap;
    if (opts.silent) {
        return;
    }
    va_start(ap, fmt);
    vlog(stderr, "WARN", fmt, ap);
    va_end(ap);
}

void log_err(const char *fmt, ...) {
    va_list ap;
    if (opts.silent) {
        return;
    }
    va_start(ap, fmt);
    vlog(stderr, "ERR", fmt, ap);
    va_end(ap);
}

void die(const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    vlog(stderr, "ERR", fmt, ap);
    va_end(ap);
    exit(2);
}

void *ag_malloc(size_t size) {
    void *p = malloc(size);
    if (p == NULL) {
        die("Memory allocation failed.");
    }
    return p;
}

void *ag_realloc(void *ptr, size_t size) {
    void *p = realloc(ptr, size);
    if (p == NULL) {
        die("Memory allocation failed.");
    }
    return p;
}

void *ag_calloc(size_t count, size_t size) {
    void *p = calloc(count, size);
    if (p == NULL) {
        die("Memory allocation failed.");
    }
    return p;
}

char *ag_strdup(const char *s) {
    char *p = strdup(s);
    if (p == NULL) {
        die("Memory allocation failed.");
    }
    return p;
}

char *ag_strndup(const char *s, size_t size) {
    char *p = strndup(s, size);
    if (p == NULL) {
        die("Memory allocation failed.");
    }
    return p;
}

int is_binary(const void *buf, const size_t buf_len) {
    size_t suspicious_bytes = 0;
    size_t total_bytes = buf_len > 512 ? 512 : buf_len;
    const unsigned char *buf_c = buf;
    size_t i;

    if (buf_len == 0) {
        return 0;
    }

    if (buf_len >= 3 && buf_c[0] == 0xEF && buf_c[1] == 0xBB && buf_c[2] == 0xBF) {
        /* UTF-8 byte order mark: text */
        return 0;
    }

    if (buf_len >= 5 && strncmp((const char *)buf, "%PDF-", 5) == 0) {
        return 1;
    }

    for (i = 0; i < total_bytes; i++) {
        if (buf_c[i] == '\0') {
            return 1;
        } else if ((buf_c[i] < 7 || buf_c[i] > 14) && (buf_c[i] < 32 || buf_c[i] > 127)) {
            /* UTF-8 sequences */
            if (buf_c[i] > 193 && buf_c[i] < 224 && i + 1 < total_bytes) {
                i++;
                if (buf_c[i] > 127 && buf_c[i] < 192) {
                    continue;
                }
            } else if (buf_c[i] > 223 && buf_c[i] < 240 && i + 2 < total_bytes) {
                i++;
                if (buf_c[i] > 127 && buf_c[i] < 192 && buf_c[i + 1] > 127 && buf_c[i + 1] < 192) {
                    i++;
                    continue;
                }
            }
            suspicious_bytes++;
            if (i >= 32 && (suspicious_bytes * 100) / total_bytes > 10) {
                return 1;
            }
        }
    }

    if ((suspicious_bytes * 100) / total_bytes > 10) {
        return 1;
    }
    return 0;
}

int is_regex(const char *query) {
    const char *regex_chars = "^$()[|\\*+?.{";
    const char *p;
    for (p = query; *p; p++) {
        if (strchr(regex_chars, *p) != NULL) {
            return 1;
        }
    }
    return 0;
}

int is_fnmatch(const char *filename) {
    const char *fnmatch_chars = "!*?[]~";
    const char *p;
    for (p = filename; *p; p++) {
        if (strchr(fnmatch_chars, *p) != NULL) {
            return 1;
        }
    }
    return 0;
}

int is_wordchar(char ch) {
    return (ch >= '0' && ch <= '9') ||
           (ch >= 'A' && ch <= 'Z') ||
           (ch >= 'a' && ch <= 'z') ||
           ch == '_';
}

/* True if the whole string parses as a base-10 integer (strtol semantics). */
int is_number_str(const char *s) {
    char *end;
    if (s == NULL || *s == '\0') {
        return 0;
    }
    errno = 0;
    strtol(s, &end, 10);
    if (end == s || *end != '\0') {
        return 0;
    }
    return 1;
}

int has_uppercase(const char *s) {
    for (; *s; s++) {
        if (*s >= 'A' && *s <= 'Z') {
            return 1;
        }
    }
    return 0;
}

/* Escape regex metacharacters so the string matches literally. */
char *escape_regex(const char *s) {
    size_t len = strlen(s);
    char *out = ag_malloc(len * 2 + 1);
    char *o = out;
    const char *special = "\\^$.[]|()?*+{}";
    for (; *s; s++) {
        if (strchr(special, *s) != NULL) {
            *o++ = '\\';
        }
        *o++ = *s;
    }
    *o = '\0';
    return out;
}

int binary_search(const char *needle, char **haystack, int start, int end) {
    int mid;
    int rc;

    if (start == end) {
        return -1;
    }
    mid = start + ((end - start) / 2);
    rc = strcmp(needle, haystack[mid]);
    if (rc < 0) {
        return binary_search(needle, haystack, start, mid);
    } else if (rc > 0) {
        return binary_search(needle, haystack, mid + 1, end);
    }
    return mid;
}

static inline int ci_eq(char a, char b) {
    return tolower((unsigned char)a) == tolower((unsigned char)b);
}

/* Find the first occurrence of find in s. Returns pointer or NULL. */
const char *literal_search(const char *s, size_t s_len, const char *find, size_t f_len, int insensitive) {
    size_t i, j;
    if (f_len == 0) {
        return s;
    }
    if (f_len > s_len) {
        return NULL;
    }
    if (!insensitive) {
        return memmem(s, s_len, find, f_len);
    }
    for (i = 0; i + f_len <= s_len; i++) {
        for (j = 0; j < f_len; j++) {
            if (!ci_eq(s[i + j], find[j])) {
                break;
            }
        }
        if (j == f_len) {
            return s + i;
        }
    }
    return NULL;
}

/*
 * Turn the list of matches into the list of regions *not* containing matches.
 * A region spans whole lines that contain no match. Regions exclude the
 * trailing newline of their last line; the final region ends at buf_len - 1.
 * Done in place; returns the new number of matches.
 */
size_t invert_matches(const char *buf, const size_t buf_len, match_t matches[], size_t matches_len) {
    size_t i;
    size_t inv = 0;
    size_t region_start = 0; /* start of the next possible region */
    match_t *out = ag_malloc(sizeof(match_t) * (matches_len + 1));

    log_debug("Inverting %u matches.", (unsigned)matches_len);

    for (i = 0; i < matches_len; i++) {
        size_t line_start = matches[i].start;
        size_t line_end = matches[i].end;
        if (line_start > buf_len) {
            line_start = buf_len;
        }
        while (line_start > 0 && buf[line_start - 1] != '\n') {
            line_start--;
        }
        if (line_end > buf_len) {
            line_end = buf_len;
        }
        while (line_end < buf_len && buf[line_end] != '\n') {
            line_end++;
        }
        if (line_start > region_start) {
            out[inv].start = region_start;
            out[inv].end = line_start - 1;
            inv++;
        }
        if (line_end + 1 > region_start) {
            region_start = line_end + 1;
        }
    }
    if (buf_len > 0 && region_start < buf_len) {
        out[inv].start = region_start;
        out[inv].end = buf_len - 1;
        inv++;
    } else if (buf_len == 0 && region_start == 0 && matches_len == 0) {
        /* empty buffer: nothing to invert */
    }

    for (i = 0; i < inv; i++) {
        matches[i] = out[i];
