int is_number_str(const char *s) {
    char *end;
    if (s == NULL || *s == '\0') {
        return 0;
    }
    errno = 0;
    strtol(s, &end, 10);
    if (end == s || *end != '\0') {
        return 0;
    }
    return 1;
}

int has_uppercase(const char *s) {
