/* Escape regex metacharacters so the string matches literally. */
char *escape_regex(const char *s) {
    size_t len = strlen(s);
    char *out = ag_malloc(len * 2 + 1);
    char *o = out;
    const char *special = "\\^$.[]|()?*+{}";
    for (; *s; s++) {
        if (strchr(special, *s) != NULL) {
            *o++ = '\\';
        }
        *o++ = *s;
    }
    *o = '\0';
    return out;
}

int binary_search(const char *needle, char **haystack, int start, int end) {
    int mid;
    int rc;

    if (start == end) {
        return -1;
    }
    mid = start + ((end - start) / 2);
    rc = strcmp(needle, haystack[mid]);
    if (rc < 0) {
        return binary_search(needle, haystack, start, mid);
    } else if (rc > 0) {
        return binary_search(needle, haystack, mid + 1, end);
    }
    return mid;
}

static inline int ci_eq(char a, char b) {
    return tolower((unsigned char)a) == tolower((unsigned char)b);
}

/* Find the first occurrence of find in s. Returns pointer or NULL. */
const char *literal_search(const char *s, size_t s_len, const char *find, size_t f_len, int insensitive) {
    size_t i, j;
    if (f_len == 0) {
        return s;
    }
    if (f_len > s_len) {
        return NULL;
    }
    if (!insensitive) {
        return memmem(s, s_len, find, f_len);
    }
    for (i = 0; i + f_len <= s_len; i++) {
        for (j = 0; j < f_len; j++) {
            if (!ci_eq(s[i + j], find[j])) {
                break;
            }
        }
        if (j == f_len) {
            return s + i;
        }
    }
    return NULL;
}

/*
 * Turn the list of matches into the list of regions *not* containing matches.
 * A region spans whole lines that contain no match. Regions exclude the
 * trailing newline of their last line; the final region ends at buf_len - 1.
 * Done in place; returns the new number of matches.
 */
size_t invert_matches(const char *buf, const size_t buf_len, match_t matches[], size_t matches_len) {
    size_t i;
    size_t inv = 0;
    size_t region_start = 0; /* start of the next possible region */
    match_t *out = ag_malloc(sizeof(match_t) * (matches_len + 1));

    log_debug("Inverting %u matches.", (unsigned)matches_len);

    for (i = 0; i < matches_len; i++) {
        size_t line_start = matches[i].start;
        size_t line_end = matches[i].end;
        if (line_start > buf_len) {
            line_start = buf_len;
        }
        while (line_start > 0 && buf[line_start - 1] != '\n') {
            line_start--;
        }
        if (line_end > buf_len) {
            line_end = buf_len;
        }
        while (line_end < buf_len && buf[line_end] != '\n') {
            line_end++;
        }
        if (line_start > region_start) {
            out[inv].start = region_start;
            out[inv].end = line_start - 1;
            inv++;
        }
        if (line_end + 1 > region_start) {
            region_start = line_end + 1;
        }
    }
    if (buf_len > 0 && region_start < buf_len) {
        out[inv].start = region_start;
        out[inv].end = buf_len - 1;
        inv++;
    } else if (buf_len == 0 && region_start == 0 && matches_len == 0) {
        /* empty buffer: nothing to invert */
    }

    for (i = 0; i < inv; i++) {
        matches[i] = out[i];
    }
    for (i = 0; i < matches_len; i++) {
        log_debug("Inverted match %u start %u end %u.", (unsigned)i, (unsigned)matches[i].start, (unsigned)matches[i].end);
    }
    free(out);
    return inv;
}

