                break;
            case LO_DEPTH:
                opts.depth = atoi(optarg);
                break;
            case LO_FILENAME:
                opts.print_path = PATH_PRINT_DEFAULT;
                opts.print_line_numbers = 1;
                break;
            case LO_NOFILENAME:
                opts.print_path = PATH_PRINT_NOTHING;
                opts.print_line_numbers = 0;
                break;
            case LO_FILENAME_PATTERN:
                needs_query = 0;
                set_file_search_regex_pattern(&file_search_pattern, optarg);
                opts.match_files = 1;
                break;
            case LO_FILE_SEARCH_REGEX:
                set_file_search_regex_pattern(&file_search_pattern, optarg);
                break;
            case LO_FILES_WITH_MATCHES:
                needs_query = 0;
                opts.print_filename_only = 1;
                opts.print_path = PATH_PRINT_TOP;
                break;
            case LO_FILES_WITHOUT_MATCHES:
                opts.print_nonmatching_files = 1;
                opts.print_path = PATH_PRINT_TOP;
                break;
            case LO_FIXED_STRINGS:
                opts.literal = 1;
                break;
            case LO_FOLLOW:
                opts.follow_symlinks = 1;
                break;
            case LO_NOFOLLOW:
                opts.follow_symlinks = 0;
                break;
            case LO_GROUP:
                group = 1;
                break;
            case LO_NOGROUP:
                group = 0;
                break;
            case LO_HEADING:
                opts.print_path = PATH_PRINT_TOP;
                break;
            case LO_NOHEADING:
                opts.print_path = PATH_PRINT_EACH_LINE;
                break;
            case LO_HELP:
                help = 1;
                break;
            case LO_HIDDEN:
                opts.search_hidden_files = 1;
                break;
            case LO_IGNORE:
                add_ignore_pattern(root_ignores, optarg);
                break;
            case LO_IGNORE_CASE:
                opts.casing = CASE_INSENSITIVE;
                break;
            case LO_INVERT_MATCH:
                opts.invert_match = 1;
                break;
            case LO_LINE_NUMBERS:
            case LO_NUMBERS:
                opts.print_line_numbers = 2;
                explicit_numbers = 1;
                break;
            case LO_NONUMBERS:
                opts.print_line_numbers = 0;
                break;
            case LO_LIST_FILE_TYPES:
                list_file_types = 1;
                break;
            case LO_LITERAL:
                opts.literal = 1;
                break;
            case LO_MATCH:
                /* no-op */
                break;
            case LO_MAX_COUNT:
                opts.max_matches = (size_t)atol(optarg);
                break;
            case LO_MMAP:
                opts.mmap = 1;
                break;
            case LO_NOMMAP:
                opts.mmap = 0;
                break;
            case LO_MULTILINE:
                opts.multiline = 1;
                break;
            case LO_NOMULTILINE:
                opts.multiline = 0;
                break;
            case LO_NOPAGER:
                out_fd = stdout;
                opts.pager = NULL;
                break;
            case LO_NORECURSE:
                opts.recurse_dirs = 0;
                break;
            case LO_RECURSE:
                opts.recurse_dirs = 1;
                break;
            case LO_NULL:
            case LO_PRINT0:
                opts.path_sep = '\0';
                break;
            case LO_ONLY_MATCHING:
                opts.only_matching = 1;
                break;
            case LO_ONE_DEVICE:
                opts.one_dev = 1;
                break;
            case LO_PAGER:
                opts.pager = optarg;
                break;
            case LO_PARALLEL:
                opts.parallel = 1;
                break;
            case LO_PASSTHROUGH:
                opts.passthrough = 1;
                break;
            case LO_PATH_TO_IGNORE:
                ignore_file_path = optarg;
                break;
            case LO_PRINT_ALL_FILES:
                opts.print_all_paths = 1;
                break;
            case LO_PRINT_LONG_LINES:
                opts.print_long_lines = 1;
                break;
            case LO_SEARCH_BINARY:
                opts.search_binary_files = 1;
                break;
            case LO_SEARCH_FILES:
                /* default behaviour */
                break;
            case LO_SEARCH_ZIP:
                opts.search_zip_files = 1;
                break;
            case LO_SILENT:
                opts.silent = 1;
                break;
            case LO_SKIP_VCS_IGNORES:
                opts.skip_vcs_ignores = 1;
                break;
            case LO_SMART_CASE:
                opts.casing = CASE_SMART;
                break;
            case LO_STATS:
                opts.stats = 1;
                break;
            case LO_STATS_ONLY:
                opts.stats = 1;
                opts.stats_only = 1;
                break;
            case LO_UNRESTRICTED:
                opts.search_binary_files = 1;
                opts.search_all_files = 1;
                opts.search_hidden_files = 1;
                break;
            case LO_VERSION:
                version = 1;
                break;
            case LO_VIMGREP:
                opts.vimgrep = 1;
                break;
            case LO_WIDTH:
                errno = 0;
                opts.width = strtol(optarg, &num_end, 10);
                if (num_end == optarg || *num_end != '\0' || errno == ERANGE) {
                    die("Invalid width\n");
                }
                break;
            case LO_WORD_REGEXP:
                opts.word_regexp = 1;
                break;
            case LO_WORKERS:
                opts.workers = atoi(optarg);
                break;
            case LO_LANG:
                lang_indices[lang_count++] = opt_index - num_longopts;
                break;
            default:
                usage();
                exit(1);
        }
    }

    if (opts.casing == CASE_DEFAULT) {
        opts.casing = CASE_SMART;
    }

    if (help) {
        usage();
        exit(0);
    }

    if (version) {
        print_version();
        exit(0);
    }

    if (list_file_types) {
        print_file_types();
        exit(0);
    }

    /* File types supersede -g/-G patterns */
    if (lang_count > 0) {
        if (file_search_pattern) {
            free(file_search_pattern);
        }
        file_search_pattern = make_lang_regex(lang_indices, lang_count);
        opts.file_search_regex_set = 2; /* language regex: always case sensitive */
    } else if (file_search_pattern) {
        opts.file_search_regex_set = 1;
    }
    free(lang_indices);

    if (opts.context > 0) {
        opts.before = opts.context;
        opts.after = opts.context;
    }

    if (opts.ackmate) {
        opts.color = 0;
        opts.print_break = 1;
        group = 1;
        opts.search_stream = 0;
    }

    if (opts.vimgrep) {
        opts.color = 0;
        opts.print_break = 0;
        group = 0;
        opts.search_stream = 0;
        opts.print_path = PATH_PRINT_EACH_LINE;
        opts.column = 1;
    }

    if (opts.parallel) {
        opts.search_stream = 0;
    }

    if (!(opts.print_path != PATH_PRINT_DEFAULT || opts.print_break == 0)) {
        /* nothing explicit about heading/break */
    }

    argc -= optind;
    argv += optind;

    if (opts.match_files) {
        needs_query = 0;
    }

    if (needs_query && argc == 0) {
        log_err("What do you want to search for?");
        exit(1);
    }

    if (home_dir && !opts.search_all_files) {
        log_debug("Found user's home dir: %s", home_dir);
        char *agignore = ag_malloc(strlen(home_dir) + strlen("/.agignore") + 1);
        sprintf(agignore, "%s/.agignore", home_dir);
        load_ignore_patterns(root_ignores, agignore);
        free(agignore);
    }

    if (!opts.skip_vcs_ignores) {
        /* git's global excludes file */
        char git_cmd[] = "git config -z --path --get core.excludesfile";
        FILE *gitconfig_res = popen(git_cmd, "r");
        char *excludes = ag_malloc(4096);
        excludes[0] = '\0';
        if (gitconfig_res) {
            size_t n = fread(excludes, 1, 4095, gitconfig_res);
            excludes[n] = '\0';
            pclose(gitconfig_res);
        }
        if (excludes[0] == '\0') {
            const char *xdg = getenv("XDG_CONFIG_HOME");
            if (xdg) {
                snprintf(excludes, 4096, "%s/git/ignore", xdg);
            } else if (home_dir) {
                snprintf(excludes, 4096, "%s/.config/git/ignore", home_dir);
            } else {
                excludes[0] = '\0';
            }
        }
        log_debug("global core.excludesfile: %s", excludes);
        load_ignore_patterns(root_ignores, excludes);
        free(excludes);
    }

    if (ignore_file_path) {
        load_ignore_patterns(root_ignores, ignore_file_path);
    }

    if (opts.match_files) {
        opts.query = ag_strdup(".");
        opts.query_len = 1;
        /* all remaining args are paths */
        path_len = argc;
    } else if (argc > 0) {
        opts.query = ag_strdup(argv[0]);
        opts.query_len = strlen(opts.query);
        argc--;
        argv++;
        path_len = argc;
    } else {
        /* -l with no pattern */
        opts.query = ag_strdup(".");
        opts.query_len = 1;
        path_len = 0;
    }

    if (opts.query_len == 0) {
        if (opts.print_filename_only) {
            free(opts.query);
            opts.query = ag_strdup(".");
            opts.query_len = 1;
        } else {
            log_err("Error: No query. What do you want to search for?");
            exit(1);
        }
    }

    if (!is_regex(opts.query)) {
        opts.literal = 1;
    }

    /* paths */
    if (path_len > 0) {
        *paths = ag_calloc(sizeof(char *), path_len + 1);
        *base_paths = ag_calloc(sizeof(char *), path_len + 1);
        for (i = 0; i < (size_t)path_len; i++) {
            char *path = ag_strdup(argv[i]);
            size_t len = strlen(path);
            /* kill trailing slash */
            if (len > 1 && path[len - 1] == '/') {
                path[len - 1] = '\0';
            }
            (*paths)[i] = path;
            char *tmp = realpath(path, NULL);
            if (tmp == NULL) {
                tmp = ag_strdup(path);
            }
            /* base_path gets a trailing slash for explicitly given paths */
            size_t tlen = strlen(tmp);
            char *bp = ag_malloc(tlen + 2);
            memcpy(bp, tmp, tlen);
            bp[tlen] = '/';
            bp[tlen + 1] = '\0';
            free(tmp);
            (*base_paths)[i] = bp;
        }
        (*paths)[path_len] = NULL;
        (*base_paths)[path_len] = NULL;
        opts.search_stream = 0; /* paths given: don't read stdin */
        opts.paths_len = path_len;
    } else {
        *paths = ag_calloc(sizeof(char *), 2);
        *base_paths = ag_calloc(sizeof(char *), 2);
        (*paths)[0] = ag_strdup(".");
        char *tmp = realpath(".", NULL);
        (*base_paths)[0] = tmp ? tmp : ag_strdup(".");
        (*paths)[1] = NULL;
        (*base_paths)[1] = NULL;
        opts.paths_len = 1;
    }

    /* stream-style output if stdin is a pipe or regular file */
    rv = fstat(fileno(stdin), &statbuf);
    if (rv == 0 && (S_ISFIFO(statbuf.st_mode) || S_ISREG(statbuf.st_mode)) && !opts.ackmate && !opts.vimgrep && !opts.parallel) {
        opts.stream_format = 1;
    }

    /* Searching a single regular file */
    if (path_len == 1 && !opts.stream_format) {
        if (stat((*paths)[0], &statbuf) == 0 && S_ISREG(statbuf.st_mode)) {
            opts.single_file = 1;
        }
    }
    if (opts.single_file) {
        if (opts.print_path == PATH_PRINT_DEFAULT) {
            opts.print_path = PATH_PRINT_NOTHING;
        }
        if (opts.only_matching && opts.print_path == PATH_PRINT_NOTHING) {
            opts.print_line_numbers = 0;
        }
    }

    if (opts.print_path == PATH_PRINT_DEFAULT) {
        if (opts.print_break == 1 && !group) {
            opts.print_path = PATH_PRINT_EACH_LINE;
            opts.print_break = 0;
        } else {
            opts.print_path = PATH_PRINT_TOP;
        }
    }

    if (opts.stream_format) {
        opts.print_path = PATH_PRINT_NOTHING;
        opts.print_break = 0;
        if (opts.print_line_numbers != 2) {
            opts.print_line_numbers = 0;
        }
    }
    (void)explicit_numbers;
    (void)useless;

    /* compile the file search regex */
    if (file_search_pattern) {
        int pcre_opts = 0;
        char *pat = file_search_pattern;
        if (opts.file_search_regex_set == 1) {
            if (opts.casing == CASE_INSENSITIVE) {
                pcre_opts |= PCRE_CASELESS;
            } else if (opts.casing == CASE_SMART && !has_uppercase(file_search_pattern)) {
                pcre_opts |= PCRE_CASELESS;
            }
            if (opts.word_regexp) {
                pat = ag_malloc(strlen(file_search_pattern) + 10);
                sprintf(pat, "\\b(?:%s)\\b", file_search_pattern);
            }
        }
        compile_study(&opts.file_search_regex, &opts.file_search_regex_extra, pat, pcre_opts, 0);
        if (pat != file_search_pattern) {
            free(pat);
        }
        free(file_search_pattern);
    }

    free(longopts);
}
