PYEOF
echo ok"}

actions.command:
cd /workspace/src && python3 - <<'PYEOF'
# Rewrite options.c: keep the top part (tables, usage) and append the parser.
src = open('options.c').read()
idx = src.index('void init_options(void)')
src = src[:idx]
src += r'''
static int group_default = 1;

void init_options(void) {
    char *term = getenv("TERM");
    memset(&opts, 0, sizeof(opts));
    opts.casing = CASE_DEFAULT;
    opts.color = TRUE;
    if (term && !strcmp(term, "dumb")) {
        opts.color = FALSE;
    }
    opts.color_line_number = ag_strdup("\033[1;33m");
    opts.color_match = ag_strdup("\033[30;43m");
    opts.color_path = ag_strdup("\033[1;32m");
    opts.max_matches = 0;
    opts.multiline = TRUE;
    opts.width = 0;
    opts.path_sep = '\n';
    opts.print_break = TRUE;
    opts.print_path = PATH_PRINT_DEFAULT;
    opts.print_all_paths = FALSE;
    opts.print_line_numbers = TRUE;
    opts.recurse_dirs = TRUE;
    opts.depth = 25;
    opts.mmap = TRUE;
    opts.use_thread_affinity = TRUE;
    opts.stream_line_num = 0;
}

void cleanup_options(void) {
    free(opts.color_line_number);
    free(opts.color_match);
    free(opts.color_path);
    if (opts.query) {
        free(opts.query);
    }
    if (opts.re) {
        pcre_free(opts.re);
    }
    if (opts.re_extra) {
        pcre_free_study(opts.re_extra);
    }
    if (opts.file_search_regex) {
        pcre_free(opts.file_search_regex);
    }
    if (opts.file_search_regex_extra) {
        pcre_free_study(opts.file_search_regex_extra);
    }
}

static char *make_color(const char *code) {
    size_t len = strlen(code);
    char *s = ag_malloc(len + 4);
    sprintf(s, "\033[%sm", code);
    return s;
}

/* Handle an optional numeric argument for -A/-B/-C style options. */
static long optional_number(int argc, char **argv, long default_value) {
    if (optarg) {
        if (is_number_str(optarg)) {
            return strtol(optarg, NULL, 10);
        }
        /* Not a number: pretend the argument wasn't consumed. */
        optind--;
        return default_value;
    }
    if (optind < argc && is_number_str(argv[optind])) {
        long v = strtol(argv[optind], NULL, 10);
        optind++;
        return v;
    }
    return default_value;
}

static void set_file_search_regex_pattern(char **pattern, const char *arg) {
    if (*pattern != NULL) {
        log_err("File search regex (-g or -G) already specified.");
        usage();
        exit(1);
    }
    *pattern = ag_strdup(arg);
}

void parse_options(int argc, char **argv, char **base_paths[], char **paths[]) {
    int ch;
    size_t i, j;
    int path_len = 0;
    int useless = 0;
    int group = 1;
    int help = 0;
    int version = 0;
    int list_file_types = 0;
    int opt_index = 0;
    char *num_end;
    const char *home_dir = getenv("HOME");
    char *ignore_file_path = NULL;
    int needs_query = 1;
    struct stat statbuf;
    int rv;
    size_t lang_count = 0;
    size_t *lang_indices = NULL;
    char *file_search_pattern = NULL;
    size_t num_longopts = sizeof(base_longopts) / sizeof(base_longopts[0]);
    struct option *longopts;
    int explicit_numbers = 0;

    init_options();

    /* Build the getopt table: regular options, then file types */
    longopts = ag_calloc(num_longopts + langs_len + 1, sizeof(struct option));
    for (i = 0; i < num_longopts; i++) {
        longopts[i].name = base_longopts[i].name;
        longopts[i].has_arg = base_longopts[i].has_arg;
        longopts[i].flag = NULL;
        longopts[i].val = base_longopts[i].val;
    }
    for (j = 0; j < langs_len; j++) {
        longopts[num_longopts + j].name = langs[j].name;
        longopts[num_longopts + j].has_arg = no_argument;
        longopts[num_longopts + j].flag = NULL;
        longopts[num_longopts + j].val = LO_LANG;
    }
    lang_indices = ag_calloc(langs_len + 1, sizeof(size_t));

    if (argc < 2) {
        usage();
        cleanup_ignore(root_ignores);
        exit(1);
    }

    rv = fstat(fileno(stdin), &statbuf);
    if (rv == 0) {
        if (S_ISFIFO(statbuf.st_mode) || S_ISREG(statbuf.st_mode)) {
            opts.search_stream = 1;
        }
    }

    /* If we're not outputting to a terminal, don't use colors or grouping by default. */
    if (!isatty(fileno(stdout))) {
        opts.color = 0;
        group = 0;
    }
    group_default = group;

    opterr = 1;
    while ((ch = getopt_long(argc, argv, "A::B::C::DF:G:g:HiLlm:nop:QRrSsvVtuUwW:z0acfh", longopts, &opt_index)) != -1) {
        switch (ch) {
            case 'A':
                opts.after = (size_t)optional_number(argc, argv, DEFAULT_AFTER_LEN);
                break;
            case 'B':
                opts.before = (size_t)optional_number(argc, argv, DEFAULT_BEFORE_LEN);
                break;
            case 'C':
                opts.context = (int)optional_number(argc, argv, DEFAULT_CONTEXT_LEN);
                break;
            case 'a':
                opts.search_all_files = 1;
                opts.search_binary_files = 1;
                break;
            case 'c':
                opts.print_count = 1;
                break;
            case 'D':
                opts.debug = 1;
                break;
            case 'f':
                opts.follow_symlinks = 1;
                break;
            case 'F':
            case 'Q':
                opts.literal = 1;
                break;
            case 'g':
                needs_query = 0;
                set_file_search_regex_pattern(&file_search_pattern, optarg);
                opts.match_files = 1;
                break;
            case 'G':
                set_file_search_regex_pattern(&file_search_pattern, optarg);
                break;
            case 'h':
                help = 1;
                break;
            case 'H':
                opts.print_path = PATH_PRINT_TOP;
                break;
            case 'i':
                opts.casing = CASE_INSENSITIVE;
                break;
            case 'L':
                opts.print_nonmatching_files = 1;
                opts.print_path = PATH_PRINT_TOP;
                break;
            case 'l':
                needs_query = 0;
                opts.print_filename_only = 1;
                opts.print_path = PATH_PRINT_TOP;
                break;
            case 'm':
                opts.max_matches = (size_t)atol(optarg);
                break;
            case 'n':
                opts.recurse_dirs = 0;
                break;
            case 'p':
                ignore_file_path = optarg;
                break;
            case 'o':
                opts.only_matching = 1;
                break;
            case 'R':
            case 'r':
                opts.recurse_dirs = 1;
                break;
            case 'S':
                opts.casing = CASE_SMART;
                break;
            case 's':
                opts.casing = CASE_SENSITIVE;
                break;
            case 't':
                opts.search_all_files = 1;
                opts.search_binary_files = 0;
                break;
            case 'u':
                opts.search_binary_files = 1;
                opts.search_all_files = 1;
                opts.search_hidden_files = 1;
                break;
            case 'U':
                opts.skip_vcs_ignores = 1;
                break;
            case 'v':
                opts.invert_match = 1;
                break;
            case 'V':
                version = 1;
                break;
            case 'w':
                opts.word_regexp = 1;
                break;
            case 'W':
                errno = 0;
                opts.width = strtol(optarg, &num_end, 10);
                if (num_end == optarg || *num_end != '\0' || errno == ERANGE) {
                    die("Invalid width\n");
                }
                break;
            case 'z':
                opts.search_zip_files = 1;
                break;
            case '0':
                opts.path_sep = '\0';
                break;
            case LO_ACKMATE:
                opts.ackmate = 1;
                break;
            case LO_ACKMATE_DIR_FILTER:
                compile_study(&opts.ackmate_dir_filter, &opts.ackmate_dir_filter_extra, optarg, 0, 0);
                break;
            case LO_AFFINITY:
                opts.use_thread_affinity = 1;
                break;
            case LO_NOAFFINITY:
                opts.use_thread_affinity = 0;
                break;
            case LO_AFTER:
                opts.after = (size_t)optional_number(argc, argv, DEFAULT_AFTER_LEN);
                break;
            case LO_BEFORE:
                opts.before = (size_t)optional_number(argc, argv, DEFAULT_BEFORE_LEN);
                break;
            case LO_CONTEXT:
                opts.context = (int)optional_number(argc, argv, DEFAULT_CONTEXT_LEN);
                break;
            case LO_ALL_TEXT:
                opts.search_all_files = 1;
                opts.search_binary_files = 0;
                break;
            case LO_ALL_TYPES:
                opts.search_all_files = 1;
                opts.search_binary_files = 1;
                break;
            case LO_BREAK:
                opts.print_break = 1;
                break;
            case LO_NOBREAK:
                opts.print_break = 0;
                break;
            case LO_CASE_SENSITIVE:
                opts.casing = CASE_SENSITIVE;
                break;
            case LO_COLOR:
                opts.color = 1;
                break;
            case LO_NOCOLOR:
                opts.color = 0;
                break;
            case LO_COLOR_X:
                if (strcmp(longopts[opt_index].name, "color-line-number") == 0) {
                    free(opts.color_line_number);
                    opts.color_line_number = make_color(optarg);
                } else if (strcmp(longopts[opt_index].name, "color-match") == 0) {
                    free(opts.color_match);
                    opts.color_match = make_color(optarg);
                } else {
                    free(opts.color_path);
                    opts.color_path = make_color(optarg);
                }
                break;
            case LO_COLOR_WIN_ANSI:
                break;
            case LO_COLUMN:
                opts.column = 1;
                break;
            case LO_COUNT:
                opts.print_count = 1;
                break;
            case LO_DEBUG:
                opts.debug = 1;
                break;
            case LO_DEPTH:
                opts.depth = atoi(optarg);
                break;
            case LO_FILENAME:
                opts.print_path = PATH_PRINT_DEFAULT;
                opts.print_line_numbers = 1;
                break;
            case LO_NOFILENAME:
                opts.print_path = PATH_PRINT_NOTHING;
                opts.print_line_numbers = 0;
                break;
            case LO_FILENAME_PATTERN:
                needs_query = 0;
                set_file_search_regex_pattern(&file_search_pattern, optarg);
                opts.match_files = 1;
                break;
            case LO_FILE_SEARCH_REGEX:
                set_file_search_regex_pattern(&file_search_pattern, optarg);
                break;
            case LO_FILES_WITH_MATCHES:
                needs_query = 0;
