                opts.print_path = PATH_PRINT_TOP;
                break;
            case LO_FILES_WITHOUT_MATCHES:
                opts.print_nonmatching_files = 1;
                opts.print_path = PATH_PRINT_TOP;
                break;
            case LO_FIXED_STRINGS:
                opts.literal = 1;
                break;
            case LO_FOLLOW:
                opts.follow_symlinks = 1;
                break;
            case LO_NOFOLLOW:
                opts.follow_symlinks = 0;
                break;
            case LO_GROUP:
                group = 1;
                break;
            case LO_NOGROUP:
                group = 0;
                break;
            case LO_HEADING:
                opts.print_path = PATH_PRINT_TOP;
                break;
            case LO_NOHEADING:
                opts.print_path = PATH_PRINT_EACH_LINE;
                break;
            case LO_HELP:
                help = 1;
                break;
            case LO_HIDDEN:
                opts.search_hidden_files = 1;
                break;
            case LO_IGNORE:
                add_ignore_pattern(root_ignores, optarg);
                break;
            case LO_IGNORE_CASE:
                opts.casing = CASE_INSENSITIVE;
                break;
            case LO_INVERT_MATCH:
                opts.invert_match = 1;
                break;
            case LO_LINE_NUMBERS:
            case LO_NUMBERS:
                opts.print_line_numbers = 2;
                explicit_numbers = 1;
                break;
            case LO_NONUMBERS:
                opts.print_line_numbers = 0;
                break;
            case LO_LIST_FILE_TYPES:
                list_file_types = 1;
                break;
            case LO_LITERAL:
                opts.literal = 1;
                break;
            case LO_MATCH:
                /* no-op */
                break;
            case LO_MAX_COUNT:
                opts.max_matches = (size_t)atol(optarg);
                break;
            case LO_MMAP:
                opts.mmap = 1;
                break;
            case LO_NOMMAP:
                opts.mmap = 0;
                break;
            case LO_MULTILINE:
                opts.multiline = 1;
                break;
            case LO_NOMULTILINE:
                opts.multiline = 0;
                break;
            case LO_NOPAGER:
                out_fd = stdout;
                opts.pager = NULL;
                break;
            case LO_NORECURSE:
                opts.recurse_dirs = 0;
                break;
            case LO_RECURSE:
                opts.recurse_dirs = 1;
                break;
            case LO_NULL:
            case LO_PRINT0:
                opts.path_sep = '\0';
                break;
            case LO_ONLY_MATCHING:
                opts.only_matching = 1;
                break;
            case LO_ONE_DEVICE:
                opts.one_dev = 1;
                break;
            case LO_PAGER:
                opts.pager = optarg;
                break;
            case LO_PARALLEL:
                opts.parallel = 1;
                break;
            case LO_PASSTHROUGH:
                opts.passthrough = 1;
                break;
            case LO_PATH_TO_IGNORE:
                ignore_file_path = optarg;
                break;
            case LO_PRINT_ALL_FILES:
                opts.print_all_paths = 1;
                break;
            case LO_PRINT_LONG_LINES:
                opts.print_long_lines = 1;
                break;
            case LO_SEARCH_BINARY:
                opts.search_binary_files = 1;
                break;
            case LO_SEARCH_FILES:
                /* default behaviour */
                break;
            case LO_SEARCH_ZIP:
                opts.search_zip_files = 1;
                break;
            case LO_SILENT:
                opts.silent = 1;
                break;
            case LO_SKIP_VCS_IGNORES:
                opts.skip_vcs_ignores = 1;
                break;
            case LO_SMART_CASE:
                opts.casing = CASE_SMART;
                break;
            case LO_STATS:
                opts.stats = 1;
                break;
            case LO_STATS_ONLY:
                opts.stats = 1;
                opts.stats_only = 1;
                break;
            case LO_UNRESTRICTED:
                opts.search_binary_files = 1;
                opts.search_all_files = 1;
                opts.search_hidden_files = 1;
                break;
            case LO_VERSION:
                version = 1;
                break;
            case LO_VIMGREP:
                opts.vimgrep = 1;
                break;
            case LO_WIDTH:
                errno = 0;
                opts.width = strtol(optarg, &num_end, 10);
                if (num_end == optarg || *num_end != '\0' || errno == ERANGE) {
                    die("Invalid width\n");
                }
                break;
            case LO_WORD_REGEXP:
                opts.word_regexp = 1;
                break;
            case LO_WORKERS:
                opts.workers = atoi(optarg);
                break;
            case LO_LANG:
                lang_indices[lang_count++] = opt_index - num_longopts;
                break;
            default:
                usage();
                exit(1);
        }
    }

    if (opts.casing == CASE_DEFAULT) {
        opts.casing = CASE_SMART;
    }

    if (help) {
        usage();
        exit(0);
    }

    if (version) {
        print_version();
        exit(0);
    }

    if (list_file_types) {
        print_file_types();
        exit(0);
    }

    /* File types supersede -g/-G patterns */
    if (lang_count > 0) {
        if (file_search_pattern) {
            free(file_search_pattern);
        }
        file_search_pattern = make_lang_regex(lang_indices, lang_count);
        opts.file_search_regex_set = 2; /* language regex: always case sensitive */
    } else if (file_search_pattern) {
        opts.file_search_regex_set = 1;
    }
    free(lang_indices);

    if (opts.context > 0) {
        opts.before = opts.context;
        opts.after = opts.context;
    }

    if (opts.ackmate) {
        opts.color = 0;
        opts.print_break = 1;
        group = 1;
        opts.search_stream = 0;
    }

    if (opts.vimgrep) {
        opts.color = 0;
        opts.print_break = 0;
        group = 0;
        opts.search_stream = 0;
        opts.print_path = PATH_PRINT_EACH_LINE;
        opts.column = 1;
    }

    if (opts.parallel) {
        opts.search_stream = 0;
    }

    if (!(opts.print_path != PATH_PRINT_DEFAULT || opts.print_break == 0)) {
        /* nothing explicit about heading/break */
    }

    argc -= optind;
    argv += optind;

    if (opts.match_files) {
        needs_query = 0;
    }

    if (needs_query && argc == 0) {
        log_err("What do you want to search for?");
        exit(1);
    }

    if (home_dir && !opts.search_all_files) {
        log_debug("Found user's home dir: %s", home_dir);
        char *agignore = ag_malloc(strlen(home_dir) + strlen("/.agignore") + 1);
        sprintf(agignore, "%s/.agignore", home_dir);
        load_ignore_patterns(root_ignores, agignore);
        free(agignore);
    }

    if (!opts.skip_vcs_ignores) {
        /* git's global excludes file */
        char git_cmd[] = "git config -z --path --get core.excludesfile";
        FILE *gitconfig_res = popen(git_cmd, "r");
        char *excludes = ag_malloc(4096);
        excludes[0] = '\0';
        if (gitconfig_res) {
            size_t n = fread(excludes, 1, 4095, gitconfig_res);
            excludes[n] = '\0';
            pclose(gitconfig_res);
        }
        if (excludes[0] == '\0') {
            const char *xdg = getenv("XDG_CONFIG_HOME");
            if (xdg) {
                snprintf(excludes, 4096, "%s/git/ignore", xdg);
            } else if (home_dir) {
                snprintf(excludes, 4096, "%s/.config/git/ignore", home_dir);
            } else {
                excludes[0] = '\0';
            }
        }
        log_debug("global core.excludesfile: %s", excludes);
        load_ignore_patterns(root_ignores, excludes);
        free(excludes);
    }

    if (ignore_file_path) {
        load_ignore_patterns(root_ignores, ignore_file_path);
    }

    if (opts.match_files) {
        opts.query = ag_strdup(".");
        opts.query_len = 1;
        /* all remaining args are paths */
        path_len = argc;
    } else if (argc > 0) {
        opts.query = ag_strdup(argv[0]);
        opts.query_len = strlen(opts.query);
        argc--;
        argv++;
        path_len = argc;
    } else {
        /* -l with no pattern */
        opts.query = ag_strdup(".");
        opts.query_len = 1;
        path_len = 0;
    }

    if (opts.query_len == 0) {
        if (opts.print_filename_only) {
            free(opts.query);
            opts.query = ag_strdup(".");
            opts.query_len = 1;
        } else {
            log_err("Error: No query. What do you want to search for?");
            exit(1);
        }
    }

    if (!is_regex(opts.query)) {
        opts.literal = 1;
    }

    /* paths */
    if (path_len > 0) {
        *paths = ag_calloc(sizeof(char *), path_len + 1);
        *base_paths = ag_calloc(sizeof(char *), path_len + 1);
        for (i = 0; i < (size_t)path_len; i++) {
            char *path = ag_strdup(argv[i]);
            size_t len = strlen(path);
            /* kill trailing slash */
            if (len > 1 && path[len - 1] == '/') {
                path[len - 1] = '\0';
            }
            (*paths)[i] = path;
            char *tmp = realpath(path, NULL);
            if (tmp == NULL) {
                tmp = ag_strdup(path);
            }
            /* base_path gets a trailing slash for explicitly given paths */
            size_t tlen = strlen(tmp);
            char *bp = ag_malloc(tlen + 2);
            memcpy(bp, tmp, tlen);
            bp[tlen] = '/';
            bp[tlen + 1] = '\0';
            free(tmp);
            (*base_paths)[i] = bp;
        }
        (*paths)[path_len] = NULL;
        (*base_paths)[path_len] = NULL;
        opts.search_stream = 0; /* paths given: don't read stdin */
        opts.paths_len = path_len;
    } else {
        *paths = ag_calloc(sizeof(char *), 2);
        *base_paths = ag_calloc(sizeof(char *), 2);
        (*paths)[0] = ag_strdup(".");
        char *tmp = realpath(".", NULL);
        (*base_paths)[0] = tmp ? tmp : ag_strdup(".");
        (*paths)[1] = NULL;
        (*base_paths)[1] = NULL;
        opts.paths_len = 1;
    }

    /* stream-style output if stdin is a pipe or regular file */
    rv = fstat(fileno(stdin), &statbuf);
    if (rv == 0 && (S_ISFIFO(statbuf.st_mode) || S_ISREG(statbuf.st_mode)) && !opts.ackmate && !opts.vimgrep && !opts.parallel) {
        opts.stream_format = 1;
    }

    /* Searching a single regular file */
    if (path_len == 1 && !opts.stream_format) {
        if (stat((*paths)[0], &statbuf) == 0 && S_ISREG(statbuf.st_mode)) {
            opts.single_file = 1;
        }
    }
    if (opts.single_file) {
        if (opts.print_path == PATH_PRINT_DEFAULT) {
            opts.print_path = PATH_PRINT_NOTHING;
        }
        if (opts.only_matching && opts.print_path == PATH_PRINT_NOTHING) {
            opts.print_line_numbers = 0;
        }
    }

    if (opts.print_path == PATH_PRINT_DEFAULT) {
        if (opts.print_break == 1 && !group) {
            opts.print_path = PATH_PRINT_EACH_LINE;
            opts.print_break = 0;
        } else {
            opts.print_path = PATH_PRINT_TOP;
        }
    }

    if (opts.stream_format) {
        opts.print_path = PATH_PRINT_NOTHING;
        opts.print_break = 0;
        if (opts.print_line_numbers != 2) {
            opts.print_line_numbers = 0;
        }
    }
    (void)explicit_numbers;
    (void)useless;

    /* compile the file search regex */
    if (file_search_pattern) {
        int pcre_opts = 0;
        char *pat = file_search_pattern;
        if (opts.file_search_regex_set == 1) {
            if (opts.casing == CASE_INSENSITIVE) {
                pcre_opts |= PCRE_CASELESS;
            } else if (opts.casing == CASE_SMART && !has_uppercase(file_search_pattern)) {
                pcre_opts |= PCRE_CASELESS;
            }
            if (opts.word_regexp) {
                pat = ag_malloc(strlen(file_search_pattern) + 10);
                sprintf(pat, "\\b(?:%s)\\b", file_search_pattern);
            }
        }
        compile_study(&opts.file_search_regex, &opts.file_search_regex_extra, pat, pcre_opts, 0);
        if (pat != file_search_pattern) {
            free(pat);
        }
        free(file_search_pattern);
    }

    free(longopts);
}
'''
open('options.c', 'w').write(src)
PYEOF
echo ok

output.arguments:
{"command":"cd /workspace/src && cat > ignore.c <<'EOF'
#include "ignore.h"
#include <fnmatch.h>
#include <ctype.h>
#include <sys/stat.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>

ignores *root_ignores = NULL;

static const char *ignore_pattern_files[] = {
    ".ignore",
    ".gitignore",
    ".git/info/exclude",
    ".hgignore",
    NULL
};

/* Files (relative to a dir) that are consulted for ignore patterns. VCS ones
 * are skipped with -U. */
const char **get_ignore_pattern_files(void) {
    return ignore_pattern_files;
}

ignores *init_ignore(ignores *parent, const char *dirname, size_t dirname_len) {
    ignores *ig = ag_calloc(1, sizeof(ignores));
    ig->parent = parent;
    ig->abs_path = ag_strndup(dirname, dirname_len);
    ig->abs_path_len = dirname_len;
    return ig;
}

static void free_list(char **list, size_t len) {
    size_t i;
    for (i = 0; i < len; i++) {
        free(list[i]);
    }
    free(list);
}

void cleanup_ignore(ignores *ig) {
    if (ig == NULL) {
        return;
    }
    free_list(ig->names, ig->names_len);
    free_list(ig->slash_names, ig->slash_names_len);
    free_list(ig->regexes, ig->regexes_len);
    free_list(ig->slash_regexes, ig->slash_regexes_len);
    free(ig->abs_path);
    free(ig);
}

/* Insert pattern into a sorted array */
static void sorted_insert(char ***list_p, size_t *len_p, const char *pattern, size_t pattern_len) {
    size_t i;
    char **list;
    (*len_p)++;
    *list_p = list = ag_realloc(*list_p, (*len_p) * sizeof(char *));
    for (i = *len_p - 1; i > 0; i--) {
        if (strcmp(pattern, list[i - 1]) > 0) {
            break;
        }
        list[i] = list[i - 1];
    }
    list[i] = ag_strndup(pattern, pattern_len);
}

void add_ignore_pattern(ignores *ig, const char *pattern) {
    size_t pattern_len;

    /* strip a leading "./" */
    if (strncmp(pattern, "./", 2) == 0) {
        pattern++;
    }

    /* trim trailing whitespace */
    for (pattern_len = strlen(pattern); pattern_len > 0; pattern_len--) {
        if (!isspace((unsigned char)pattern[pattern_len - 1])) {
            break;
        }
    }

    if (pattern_len == 0) {
        log_debug("Pattern is empty. Not adding any ignores.");
        return;
    }

    if (is_fnmatch(pattern)) {
        if (pattern[0] == '/') {
            pattern++;
            pattern_len--;
            sorted_insert(&ig->slash_regexes, &ig->slash_regexes_len, pattern, pattern_len);
        } else {
            sorted_insert(&ig->regexes, &ig->regexes_len, pattern, pattern_len);
        }
    } else {
        if (pattern[0] == '/') {
            pattern++;
            pattern_len--;
            sorted_insert(&ig->slash_names, &ig->slash_names_len, pattern, pattern_len);
        } else {
            sorted_insert(&ig->names, &ig->names_len, pattern, pattern_len);
        }
    }
    {
        char *shown = ag_strndup(pattern, pattern_len);
        const char *s = shown;
        if (s[0] == '!') {
            s++;
        }
        log_debug("added ignore pattern %s to %s", s,
                  ig == root_ignores ? "root ignores" : ig->abs_path);
        free(shown);
    }
}

void load_ignore_patterns(ignores *ig, const char *path) {
    FILE *fp;
    char *line = NULL;
    ssize_t line_len;
    size_t line_cap = 0;

    fp = fopen(path, "r");
    if (fp == NULL) {
        log_debug("Skipping ignore file %s: not readable", path);
        return;
    }
    log_debug("Loading ignore file %s.", path);

    while ((line_len = getline(&line, &line_cap, fp)) > 0) {
        if (line_len > 0 && line[line_len - 1] == '\n') {
            line[line_len - 1] = '\0';
            line_len--;
        }
        if (line_len == 0) {
            continue;
        }
        if (line[0] == '#') {
            continue;
        }
        add_ignore_pattern(ig, line);
    }
    free(line);
    fclose(fp);
}

/* Does `name` match the pattern list via exact comparison? */
static int match_name_list(char **names, size_t names_len, const char *filename) {
    if (names_len == 0) {
        return 0;
    }
    return binary_search(filename, names, 0, (int)names_len) >= 0;
}

/* Check whether any contiguous component sequence of `path` equals a name. */
static const char *path_component_match(ignores *ig, const char *path) {
    const char *p = path;
    size_t i;
    while (1) {
        /* p points at the start of a component */
        for (i = 0; i < ig->names_len; i++) {
            const char *name = ig->names[i];
            size_t nlen = strlen(name);
            if (strncmp(p, name, nlen) == 0 && (p[nlen] == '\0' || p[nlen] == '/')) {
                return name;
            }
        }
        p = strchr(p, '/');
        if (p == NULL) {
            break;
        }
        p++;
    }
    return NULL;
}

/* Returns the path to check relative to the given ignore's directory. */
static const char *relative_slash_path(ignores *ig, const char *temp) {
    const char *s = temp;
    if (s[0] == '.') {
        s++;
    }
    if (s[0] == '/') {
        s++;
    }
    if (ig->abs_path_len > 0 && strncmp(s, ig->abs_path, ig->abs_path_len) == 0 && s[ig->abs_path_len] == '/') {
        s += ig->abs_path_len + 1;
    }
    return s;
}

/* Returns 1 if ignored, 0 if not ignored (and -1 if explicitly un-ignored). */
static int ignore_search_single(ignores *ig, const char *filename, const char *temp) {
    size_t i;
    const char *slash_path;
    const char *matched;

    /* static names vs bare filename */
    if (match_name_list(ig->names, ig->names_len, filename)) {
        log_debug("file %s ignored because name matches static pattern %s", filename, filename);
        return 1;
    }

    slash_path = relative_slash_path(ig, temp);

    /* static names anywhere in the path */
    matched = path_component_match(ig, slash_path);
    if (matched) {
        log_debug("file %s ignored because path somewhere matches name %s", slash_path, matched);
        return 1;
    }
    for (i = 0; i < ig->names_len; i++) {
        log_debug("pattern %s doesn't match path %s", ig->names[i], slash_path);
    }

    /* slash names: exact match on the relative path */
    if (match_name_list(ig->slash_names, ig->slash_names_len, slash_path)) {
        log_debug("file %s ignored because name matches slash static pattern %s", slash_path, slash_path);
        return 1;
    }

    /* slash regexes against the relative path */
    for (i = 0; i < ig->slash_regexes_len; i++) {
        if (fnmatch(ig->slash_regexes[i], slash_path, FNM_PATHNAME) == 0) {
            log_debug("file %s ignored because name matches slash regex pattern %s", slash_path, ig->slash_regexes[i]);
            return 1;
        }
        log_debug("pattern %s doesn't match slash file %s", ig->slash_regexes[i], slash_path);
    }

    /* regexes against the bare filename */
    for (i = 0; i < ig->regexes_len; i++) {
        const char *pat = ig->regexes[i];
        if (pat[0] == '!') {
            if (fnmatch(pat + 1, filename, FNM_PATHNAME) == 0) {
                log_debug("file %s not ignored because name matches regex pattern %s", filename, pat);
                return -1;
            }
        } else if (fnmatch(pat, filename, FNM_PATHNAME) == 0) {
            log_debug("file %s ignored because name matches regex pattern %s", filename, pat);
            return 1;
        }
        log_debug("pattern %s doesn't match file %s", pat, filename);
    }

    return 0;
}

static int is_ignored_by(ignores *ig, const char *filename, const char *temp) {
    int rc;
    while (ig != NULL) {
        rc = ignore_search_single(ig, filename, temp);
        if (rc == 1) {
            return 1;
        }
        /* a negation or no match: continue with the parent */
        ig = ig->parent;
    }
    return 0;
}

int is_dir_entry(const char *path, const struct dirent *d) {
    struct stat s;
    char *full;
    int rc;
    size_t plen;

#ifdef _DIRENT_HAVE_D_TYPE
    if (d->d_type != DT_UNKNOWN) {
        if (d->d_type == DT_DIR) {
            return 1;
        }
        if (d->d_type == DT_LNK && opts.follow_symlinks) {
            /* fall through to stat */
        } else {
            return 0;
        }
    }
#endif
    plen = strlen(path);
    full = ag_malloc(plen + strlen(d->d_name) + 2);
    sprintf(full, "%s/%s", path, d->d_name);
    rc = stat(full, &s);
    free(full);
    if (rc != 0) {
        return 0;
    }
    return S_ISDIR(s.st_mode);
}

static int ackmate_dir_match(const char *dir_name) {
    if (opts.ackmate_dir_filter == NULL) {
        return 1;
    }
    return pcre_exec(opts.ackmate_dir_filter, opts.ackmate_dir_filter_extra, dir_name, strlen(dir_name), 0, 0, NULL, 0) >= 0;
}

/* One pass of the filter for a given name (either "name" or "name/"). */
static int filter_pass(scandir_baton_t *baton, const char *filename, size_t filename_len) {
    const char *path_start = baton->path_start;
    size_t path_len = strlen(path_start);
    char *temp = ag_malloc(path_len + filename_len + 2);
    const char *slash_for_ackmate;
    int rc = 1;

    memcpy(temp, path_start, path_len);
    temp[path_len] = '/';
    memcpy(temp + path_len + 1, filename, filename_len);
    temp[path_len + 1 + filename_len] = '\0';

    slash_for_ackmate = temp;
    if (slash_for_ackmate[0] == '.') {
        slash_for_ackmate++;
    }
    if (!ackmate_dir_match(slash_for_ackmate)) {
        rc = 0;
    } else if (is_ignored_by(baton->ig, filename, temp)) {
        rc = 0;
    }
    free(temp);
    return rc;
}

/* Returns 1 if the entry should be kept. */
int filename_filter(const char *path, const struct dirent *dir, void *baton_v) {
    scandir_baton_t *baton = baton_v;
    const char *filename = dir->d_name;
    size_t filename_len;
    char *with_slash;
    int isdir;

    if (strcmp(filename, ".") == 0 || strcmp(filename, "..") == 0) {
        return 0;
    }

    if (!opts.search_hidden_files && filename[0] == '.') {
        return 0;
    }

    if (!opts.follow_symlinks && dir->d_type == DT_LNK) {
        log_debug("File %s ignored becaused it's a symlink", filename);
        return 0;
    }

    if (opts.search_all_files && !opts.ackmate_dir_filter) {
        return 1;
    }

    filename_len = strlen(filename);

    if (!opts.search_all_files) {
        if (!filter_pass(baton, filename, filename_len)) {
            return 0;
        }
    } else {
        /* only the ackmate filter applies */
        if (!filter_pass(baton, filename, filename_len)) {
            return 0;
        }
    }

