cat > print.c <<'EOF'
#include "print.h"
#include <limits.h>

const char *color_reset = "\033[0m\033[K";

static int first_file_match = 1;
static pthread_mutex_t sep_mtx = PTHREAD_MUTEX_INITIALIZER;

void print_context_init(print_context_t *ctx, int is_stream, int is_stdin) {
    memset(ctx, 0, sizeof(*ctx));
    ctx->ring_size = opts.before + 1;
    ctx->context_prev_lines = ag_calloc(ctx->ring_size, sizeof(char *));
    ctx->last_prev_line = 0;
    ctx->lines_since_last_match = INT_MAX;
    ctx->line = 1;
    ctx->prev_line_offset = 0;
    ctx->in_a_match = FALSE;
    ctx->printing_a_match = FALSE;
    ctx->is_stream = is_stream;
    ctx->is_stdin = is_stdin;
}

void print_context_free(print_context_t *ctx) {
    size_t i;
    if (ctx->context_prev_lines) {
        for (i = 0; i < ctx->ring_size; i++) {
            free(ctx->context_prev_lines[i]);
        }
        free(ctx->context_prev_lines);
    }
    ctx->context_prev_lines = NULL;
}

static void ring_store(print_context_t *ctx, const char *s, size_t len) {
    size_t idx;
    if (opts.before == 0) {
        return;
    }
    idx = ctx->last_prev_line % opts.before;
    free(ctx->context_prev_lines[idx]);
    ctx->context_prev_lines[idx] = ag_strndup(s, len);
    ctx->last_prev_line = (ctx->last_prev_line + 1) % opts.before;
}

void print_context_append(print_context_t *ctx, const char *line, size_t len) {
    ring_store(ctx, line, len);
}

static const char *normalize_path(const char *path) {
    if (path[0] == '.' && path[1] == '/') {
        return path + 2;
    }
    return path;
}

void print_path(const char *path, const char sep) {
    if (opts.print_path == PATH_PRINT_NOTHING && !opts.vimgrep) {
        return;
    }
    path = normalize_path(path);
    if (opts.ackmate) {
        fprintf(out_fd, ":%s%c", path, sep);
    } else if (opts.color) {
        fprintf(out_fd, "%s%s%s%c", opts.color_path, path, color_reset, sep);
    } else {
        fprintf(out_fd, "%s%c", path, sep);
    }
}

void print_path_count(const char *path, const char sep, const size_t count) {
    if (*path) {
        print_path(path, ':');
    }
    if (opts.color) {
        fprintf(out_fd, "%s%lu%s%c", opts.color_line_number, (unsigned long)count, color_reset, sep);
    } else {
        fprintf(out_fd, "%lu%c", (unsigned long)count, sep);
    }
}

void print_line_number(print_context_t *ctx, size_t line, const char sep) {
    if (!opts.print_line_numbers) {
        return;
    }
    (void)ctx;
    if (opts.color) {
        fprintf(out_fd, "%s%lu%s%c", opts.color_line_number, (unsigned long)line, color_reset, sep);
    } else {
        fprintf(out_fd, "%lu%c", (unsigned long)line, sep);
    }
}

static void print_column_number(const match_t matches[], size_t matches_len, size_t last_printed_match, size_t prev_line_offset, const char sep) {
    size_t column = 0;
    if (last_printed_match < matches_len && matches[last_printed_match].start >= prev_line_offset) {
        column = (matches[last_printed_match].start - prev_line_offset) + 1;
    }
    fprintf(out_fd, "%lu%c", (unsigned long)column, sep);
}

void print_file_separator(void) {
    pthread_mutex_lock(&sep_mtx);
    if (first_file_match == 0 && opts.print_break) {
        fputc('\n', out_fd);
    }
    first_file_match = 0;
    pthread_mutex_unlock(&sep_mtx);
}

void print_binary_file_matches(const char *path) {
    path = normalize_path(path);
    print_file_separator();
    fprintf(out_fd, "Binary file %s matches.\n", path);
}

/* Print buf[start..end] inclusive (used by ackmate/vimgrep). */
static void print_line(const char *buf, size_t buf_pos, size_t prev_line_offset) {
    size_t width = 0;
    if (opts.width > 0 && (size_t)opts.width < buf_pos - prev_line_offset) {
