                        print_path(path, sep);
                        print_line_number(ctx, line_num, sep);
                        print_column_number(matches, matches_len, last_printed_match, prev_line_offset, sep);
                        print_line(buf, i, prev_line_offset);
                    }
                } else {
                    int printed_match = FALSE;
                    print_line_number(ctx, line_num, ':');
                    if (opts.column) {
                        print_column_number(matches, matches_len, last_printed_match, prev_line_offset, ':');
