                        }
                        /* truncation */
                        if (j < buf_len && opts.width > 0 && j - prev_line_offset >= (size_t)opts.width) {
                            if (j < i) {
                                fputs(" [...]", out_fd);
                            }
                            fputc('\n', out_fd);
                            /* the rest of the matches on this line are never closed */
                            last_printed_match = matches_len;
                            break;
                        }
                        /* open highlight of match term */
                        if (last_printed_match < matches_len && j == matches[last_printed_match].start) {
                            if (opts.only_matching && printed_match) {
                                if (opts.print_path == PATH_PRINT_EACH_LINE && !ctx->is_stdin) {
