void print_context_free(print_context_t *ctx) {
    size_t i;
    if (ctx->context_prev_lines) {
        for (i = 0; i < ctx->ring_size; i++) {
            free(ctx->context_prev_lines[i]);
        }
        free(ctx->context_prev_lines);
    }
    ctx->context_prev_lines = NULL;
}

static void ring_store(print_context_t *ctx, const char *s, size_t len) {
    size_t idx;
    if (opts.before == 0) {
        return;
    }
    idx = ctx->last_prev_line % opts.before;
    free(ctx->context_prev_lines[idx]);
    ctx->context_prev_lines[idx] = ag_strndup(s, len);
    ctx->last_prev_line = (ctx->last_prev_line + 1) % opts.before;
}

void print_context_append(print_context_t *ctx, const char *line, size_t len) {
    ring_store(ctx, line, len);
