#include "zip.h"
#include <zlib.h>
#include <lzma.h>
#include <err.h>
#include <errno.h>
#include <signal.h>

ag_compression_type is_zipped(const void *buf, const size_t buf_len) {
    const unsigned char *b = buf;
    if (buf_len == 0) {
        return AG_NO_COMPRESSION;
    }
    if (buf_len >= 2 && b[0] == 0x1F && b[1] == 0x8B) {
        return AG_GZIP;
    }
    if (buf_len >= 4 && b[0] == 'P' && b[1] == 'K' && b[2] == 0x03 && b[3] == 0x04) {
        return AG_ZIP;
    }
    if (buf_len >= 6 && b[0] == 0xFD && b[1] == '7' && b[2] == 'z' && b[3] == 'X' && b[4] == 'Z' && b[5] == 0x00) {
        return AG_XZ;
    }
    return AG_NO_COMPRESSION;
}

static void *decompress_zlib(const void *buf, const size_t buf_len, const char *dir_full_path, size_t *new_buf_len) {
    int ret = 0;
    unsigned char *result = NULL;
    size_t result_size = 0;
    size_t pagesize = 0;
    z_stream stream;

    log_debug("Decompressing zlib file %s", dir_full_path);

    stream.zalloc = Z_NULL;
    stream.zfree = Z_NULL;
    stream.opaque = Z_NULL;
    stream.avail_in = 0;
    stream.next_in = Z_NULL;

    /* 32 + 15: autodetect gzip/zlib headers */
    ret = inflateInit2(&stream, 32 + 15);
    if (ret != Z_OK) {
        log_err("Unable to initialize zlib: %s", zError(ret));
        goto error_out;
    }

    stream.avail_in = buf_len;
    stream.next_in = (unsigned char *)buf;

    pagesize = 4096;
    result_size = ((buf_len + pagesize - 1) & ~(pagesize - 1));
    do {
        do {
            unsigned char *tmp_result = result;
            result_size *= 2;
            tmp_result = realloc(result, result_size);
            if (tmp_result == NULL) {
                free(result);
                log_err("Unable to allocate %d bytes to decompress file %s", result_size, dir_full_path);
                inflateEnd(&stream);
                goto error_out;
            }
            result = tmp_result;
            stream.avail_out = result_size / 2;
            stream.next_out = &result[stream.total_out];

            ret = inflate(&stream, Z_SYNC_FLUSH);
            log_debug("inflate ret = %d", ret);
            switch (ret) {
                case Z_STREAM_ERROR:
                    log_err("Found stream error while decompressing zlib stream: %s", zError(ret));
                    inflateEnd(&stream);
                    goto error_out;
                case Z_NEED_DICT:
                case Z_DATA_ERROR:
                    log_err("Found mem/data error while decompressing zlib stream: %s", "data error");
                    inflateEnd(&stream);
                    goto error_out;
                case Z_MEM_ERROR:
                    log_err("Found mem/data error while decompressing zlib stream: %s", "mem error");
                    inflateEnd(&stream);
                    goto error_out;
            }
        } while (stream.avail_out == 0);
    } while (ret == Z_OK);

    *new_buf_len = stream.total_out;
    inflateEnd(&stream);

    if (ret == Z_STREAM_END) {
        return result;
    }

error_out:
    *new_buf_len = 0;
    if (result) {
        free(result);
    }
    return NULL;
}

static void *decompress_lzma(const void *buf, const size_t buf_len, const char *dir_full_path, size_t *new_buf_len) {
    lzma_stream stream = LZMA_STREAM_INIT;
    lzma_ret lzrt;
    unsigned char *result = NULL;
    size_t result_size = 0;
    size_t pagesize = 4096;

    stream.avail_in = buf_len;
    stream.next_in = buf;

    lzrt = lzma_auto_decoder(&stream, -1, 0);
    if (lzrt != LZMA_OK) {
        log_err("Unable to initialize lzma_auto_decoder: %d", lzrt);
        goto error_out;
    }

    result_size = ((buf_len + pagesize - 1) & ~(pagesize - 1));
    do {
        do {
            unsigned char *tmp_result = result;
            result_size *= 2;
            tmp_result = realloc(result, result_size);
            if (tmp_result == NULL) {
                free(result);
                log_err("Unable to allocate %d bytes to decompress file %s", result_size, dir_full_path);
                lzma_end(&stream);
                goto error_out;
            }
            result = tmp_result;
            stream.avail_out = result_size / 2;
            stream.next_out = &result[stream.total_out];

            lzrt = lzma_code(&stream, LZMA_RUN);
            log_debug("lzma_code ret = %d", lzrt);
            switch (lzrt) {
                case LZMA_OK:
                case LZMA_STREAM_END:
                    break;
                default:
                    log_err("Found mem/data error while decompressing xz/lzma stream: %d", lzrt);
                    lzma_end(&stream);
                    goto error_out;
            }
        } while (stream.avail_out == 0);
    } while (lzrt == LZMA_OK);

    *new_buf_len = stream.total_out;
    lzma_end(&stream);

    if (lzrt == LZMA_STREAM_END) {
        return result;
    }

error_out:
    *new_buf_len = 0;
    if (result) {
        free(result);
    }
    return NULL;
}

void *decompress(const ag_compression_type zip_type, const void *buf, const size_t buf_len, const char *dir_full_path, size_t *new_buf_len) {
    void *res;
    switch (zip_type) {
        case AG_GZIP:
            res = decompress_zlib(buf, buf_len, dir_full_path, new_buf_len);
            break;
        case AG_XZ:
            res = decompress_lzma(buf, buf_len, dir_full_path, new_buf_len);
            break;
        case AG_COMPRESS:
        case AG_ZIP:
        default:
            log_err("Unsupported compression type: %d", zip_type);
            /* the original crashes here */
            raise(SIGSEGV);
            res = NULL;
            break;
    }
    return res;
}
