 * offsets relative to buf. */
static void find_matches(const char *buf, size_t region_start, size_t region_end, size_t buf_len,
                         const char *path, match_list_t *ml) {
    size_t buf_offset = region_start;
    int insensitive = (opts.casing == CASE_INSENSITIVE);

    if (opts.literal) {
        const char *match_ptr;
        const char *base = buf;
        while (buf_offset < region_end && !ml->stop) {
            match_ptr = literal_search(base + buf_offset, region_end - buf_offset, opts.query, opts.query_len, insensitive);
            if (match_ptr == NULL) {
                break;
            }
            {
                size_t start = (size_t)(match_ptr - base);
                size_t end = start + opts.query_len;
                if (opts.word_regexp && !word_boundary_ok(buf, buf_len, start, end)) {
                    buf_offset = start + 1;
                    continue;
                }
                log_debug("Match found. File %s, offset %lu bytes.", path, (unsigned long)start);
                add_match(ml, start, end, path);
                buf_offset = end;
                if (opts.query_len == 0) {
                    buf_offset++;
                }
            }
        }
    } else {
        int offset_vector[3];
        int rc;
        while (buf_offset < region_end && !ml->stop) {
            rc = pcre_exec(opts.re, opts.re_extra, buf, (int)region_end, (int)buf_offset, 0, offset_vector, 3);
            if (rc < 0) {
                break;
            }
            log_debug("Regex match found. File %s, offset %i bytes.", path, offset_vector[0]);
            buf_offset = offset_vector[1];
            if (offset_vector[0] == offset_vector[1]) {
                ++buf_offset;
                log_debug("Regex match is of length zero. Advancing offset one byte.");
            }
            add_match(ml, (size_t)offset_vector[0], (size_t)offset_vector[1], path);
        }
    }
}

size_t search_buf(const char *buf, const size_t buf_len, const char *dir_full_path, print_context_t *ctx) {
    int binary = -1;
    match_list_t ml;
    size_t matches_len = 0;
    int is_stdin = ctx->is_stdin;

    memset(&ml, 0, sizeof(ml));

    if (is_stdin) {
        binary = 0;
    } else if (!opts.search_binary_files) {
        binary = is_binary(buf, buf_len);
        if (binary) {
            log_debug("File %s is binary. Skipping...", dir_full_path);
            return 0;
        }
    }

    if (query_is_dot()) {
        /* match everything */
        if (buf_len > 0 || 1) {
            add_match(&ml, 0, buf_len, dir_full_path);
        }
    } else if (opts.multiline) {
        find_matches(buf, 0, buf_len, buf_len, dir_full_path, &ml);
    } else {
        /* search line by line */
        size_t line_start = 0;
        size_t i;
        for (i = 0; i <= buf_len && !ml.stop; i++) {
            if (i == buf_len || buf[i] == '\n') {
                find_matches(buf, line_start, i, buf_len, dir_full_path, &ml);
                line_start = i + 1;
            }
        }
    }
    matches_len = ml.len;

    if (opts.invert_match) {
        if (ml.matches == NULL) {
            ml.matches = ag_malloc(sizeof(match_t));
        }
        matches_len = invert_matches(buf, buf_len, ml.matches, matches_len);
    }

    if (opts.stats) {
        pthread_mutex_lock(&stats_mtx);
        stats.total_bytes += buf_len;
        stats.total_files++;
        stats.total_matches += matches_len;
        if (matches_len > 0) {
            stats.total_file_matches++;
        }
        pthread_mutex_unlock(&stats_mtx);
    }

    if (!opts.print_nonmatching_files && (matches_len > 0 || opts.print_all_paths)) {
        if (binary == -1 && !opts.print_filename_only) {
            binary = is_binary(buf, buf_len);
        }
        pthread_mutex_lock(&print_mtx);
        if (opts.print_count) {
            print_path_count(dir_full_path, opts.path_sep, matches_len);
        } else if (opts.print_filename_only) {
            print_path(dir_full_path, opts.path_sep);
        } else if (binary) {
            print_binary_file_matches(dir_full_path);
        } else {
            print_file_matches(ctx, dir_full_path, buf, buf_len, ml.matches, matches_len);
        }
        pthread_mutex_unlock(&print_mtx);
        opts.match_found = 1;
    } else if (is_stdin && opts.passthrough) {
        pthread_mutex_lock(&print_mtx);
        fwrite(buf, 1, buf_len, out_fd);
        pthread_mutex_unlock(&print_mtx);
    } else {
        log_debug("No match in %s", dir_full_path);
    }

    if (opts.print_nonmatching_files && matches_len == 0) {
        pthread_mutex_lock(&print_mtx);
        print_path(dir_full_path, opts.path_sep);
        pthread_mutex_unlock(&print_mtx);
        opts.match_found = 1;
    }

    free(ml.matches);
    return matches_len;
}

void search_stream(FILE *stream, const char *path, int is_stdin) {
    char *line = NULL;
    ssize_t line_len = 0;
    size_t line_cap = 0;
    size_t i;
    print_context_t ctx;

    print_context_init(&ctx, 1, is_stdin);

    for (i = 1; (line_len = getline(&line, &line_cap, stream)) > 0; i++) {
        size_t matches_len;
        size_t n = (size_t)line_len;
        size_t stripped = n;
        opts.stream_line_num = i;
        if (n > 0 && line[n - 1] == '\n') {
            stripped = n - 1;
        }
        if (is_stdin) {
            /* search the full line, print without the trailing newline */
            matches_len = search_buf_stream(line, n, stripped, path, &ctx);
            if (matches_len == 0) {
                pthread_mutex_lock(&print_mtx);
                print_trailing_context(&ctx, path, line, stripped);
                pthread_mutex_unlock(&print_mtx);
                print_context_append(&ctx, line, stripped);
            }
        } else {
            search_buf(line, n, path, &ctx);
            pthread_mutex_lock(&print_mtx);
            print_trailing_context(&ctx, path, line, stripped);
            pthread_mutex_unlock(&print_mtx);
        }
    }

    free(line);
    print_context_free(&ctx);
}

void search_file(const char *file_full_path) {
    int fd = -1;
    off_t f_len = 0;
    char *buf = NULL;
    struct stat statbuf;
    int rv = 0;
    FILE *fp = NULL;
    print_context_t ctx;

    rv = stat(file_full_path, &statbuf);
    if (rv != 0) {
        log_err("Skipping %s: Error fstat()ing file.", file_full_path);
        return;
    }

    fd = open(file_full_path, O_RDONLY);
    if (fd < 0) {
        log_err("Skipping %s: Error opening file: %s", file_full_path, strerror(errno));
        goto cleanup;
    }

    rv = fstat(fd, &statbuf);
    if (rv != 0) {
        log_err("Skipping %s: Error fstat()ing file.", file_full_path);
        goto cleanup;
    }

    if (S_ISFIFO(statbuf.st_mode)) {
        log_debug("%s is a named pipe. stream searching", file_full_path);
        fp = fdopen(fd, "r");
        search_stream(fp, file_full_path, 0);
        fclose(fp);
        fd = -1;
        goto cleanup;
    }

    if (!S_ISREG(statbuf.st_mode)) {
        log_err("Skipping %s: Mode %u is not a file.", file_full_path, statbuf.st_mode);
        goto cleanup;
    }

    f_len = statbuf.st_size;

    if (f_len == 0) {
        log_debug("Skipping %s: file is empty.", file_full_path);
        goto cleanup;
    }

    buf = ag_malloc((size_t)f_len + 1);
    {
        size_t total = 0;
        while (total < (size_t)f_len) {
            ssize_t r = read(fd, buf + total, (size_t)f_len - total);
            if (r < 0) {
                log_err("Skipping %s: Error reading file: %s", file_full_path, strerror(errno));
                goto cleanup;
            }
            if (r == 0) {
                break;
            }
            total += (size_t)r;
        }
        f_len = (off_t)total;
        buf[f_len] = '\0';
    }

    if (opts.search_zip_files) {
        ag_compression_type zip_type = is_zipped(buf, (size_t)f_len);
        if (zip_type != AG_NO_COMPRESSION) {
            size_t _buf_len = 0;
            char *_buf;
            log_debug("%s is a compressed file. stream searching", file_full_path);
            _buf = decompress(zip_type, buf, (size_t)f_len, file_full_path, &_buf_len);
            if (_buf == NULL || _buf_len == 0) {
                log_err("Cannot decompress zipped file %s", file_full_path);
                free(_buf);
                goto cleanup;
            }
            fp = fmemopen(_buf, _buf_len, "r");
            if (fp) {
                search_stream(fp, file_full_path, 0);
                fclose(fp);
            }
            free(_buf);
            goto cleanup;
        }
    }

    print_context_init(&ctx, 0, 0);
    search_buf(buf, (size_t)f_len, file_full_path, &ctx);
    print_context_free(&ctx);

cleanup:
    if (buf) {
        free(buf);
    }
    if (fd != -1) {
        close(fd);
    }
}

void *search_file_worker(void *i) {
    work_queue_t *queue_item;
    int worker_id = *(int *)i;

    log_debug("Worker %i started", worker_id);
    while (TRUE) {
        pthread_mutex_lock(&work_queue_mtx);
        while (work_queue == NULL) {
            if (done_adding_files) {
                pthread_mutex_unlock(&work_queue_mtx);
                log_debug("Worker %i finished.", worker_id);
                pthread_exit(NULL);
            }
            pthread_cond_wait(&files_ready, &work_queue_mtx);
        }
        queue_item = work_queue;
        work_queue = work_queue->next;
        if (work_queue == NULL) {
            work_queue_tail = NULL;
        }
        pthread_mutex_unlock(&work_queue_mtx);

        search_file(queue_item->path);
        free(queue_item->path);
        free(queue_item);
    }
    return NULL;
}

/* Check whether the directory `path` is one of the ancestors in the chain. */
typedef struct dir_chain {
    dev_t dev;
    ino_t ino;
    struct dir_chain *parent;
} dir_chain_t;

static __thread dir_chain_t *current_chain = NULL;

static int is_directory_loop(const char *path, dir_chain_t **out, struct stat *s) {
    dir_chain_t *c;
    if (stat(path, s) != 0) {
        return 0;
    }
    for (c = current_chain; c != NULL; c = c->parent) {
        if (c->dev == s->st_dev && c->ino == s->st_ino) {
            return 1;
        }
    }
    *out = ag_malloc(sizeof(dir_chain_t));
    (*out)->dev = s->st_dev;
    (*out)->ino = s->st_ino;
    (*out)->parent = current_chain;
    return 0;
}

static int ag_scandir(const char *dirname, struct dirent ***namelist, scandir_baton_t *baton) {
    DIR *dirp = NULL;
    struct dirent **names = NULL;
    struct dirent *entry, *d;
    int names_len = 32;
    int results_len = 0;

    dirp = opendir(dirname);
    if (dirp == NULL) {
        return -1;
    }

    names = ag_malloc(sizeof(struct dirent *) * names_len);

    while ((entry = readdir(dirp)) != NULL) {
        if (filename_filter(dirname, entry, baton) == 0) {
            continue;
        }
        if (results_len >= names_len) {
            names_len *= 2;
            names = ag_realloc(names, sizeof(struct dirent *) * names_len);
        }
        d = ag_malloc(sizeof(struct dirent));
        memcpy(d, entry, sizeof(struct dirent));
        names[results_len] = d;
        results_len++;
    }

    closedir(dirp);
    *namelist = names;
    return results_len;
}

void search_dir(ignores *ig, const char *base_path, const char *path, const int depth, dev_t original_dev) {
    struct dirent **dir_list = NULL;
    struct dirent *dir = NULL;
    scandir_baton_t scandir_baton;
    int results = 0;
    size_t base_path_len = 0;
    const char *path_start = path;
    const char **ignore_files;
    char *dir_full_path = NULL;
    size_t path_len = strlen(path);
    size_t i;
    dir_chain_t *chain_node = NULL;
    struct stat dir_stat;
    int in_chain = 0;

    /* The dir is in a loop if it resolves to one of its ancestors. */
    if (opts.follow_symlinks && depth > 0) {
        if (is_directory_loop(path, &chain_node, &dir_stat)) {
            log_err("Recursive directory loop: %s", path);
            return;
        }
    } else if (depth == 0) {
        if (stat(path, &dir_stat) == 0) {
            chain_node = ag_malloc(sizeof(dir_chain_t));
            chain_node->dev = dir_stat.st_dev;
            chain_node->ino = dir_stat.st_ino;
            chain_node->parent = current_chain;
        }
    } else {
        if (stat(path, &dir_stat) == 0) {
            chain_node = ag_malloc(sizeof(dir_chain_t));
            chain_node->dev = dir_stat.st_dev;
            chain_node->ino = dir_stat.st_ino;
            chain_node->parent = current_chain;
        }
    }
    if (chain_node) {
        current_chain = chain_node;
        in_chain = 1;
    }

    /* find agignore/gitignore/hgignore/etc files to load ignore patterns from */
    ignore_files = get_ignore_pattern_files();
    for (i = 0; ignore_files[i] != NULL; i++) {
        if (opts.skip_vcs_ignores && i > 0) {
            break;
        }
        dir_full_path = ag_malloc(path_len + strlen(ignore_files[i]) + 2);
        sprintf(dir_full_path, "%s/%s", path, ignore_files[i]);
        load_ignore_patterns(ig, dir_full_path);
        free(dir_full_path);
        dir_full_path = NULL;
    }

    /* path_start: path relative to the base */
    {
        char *base_nos = ag_strdup(base_path);
        size_t bl = strlen(base_nos);
        if (bl > 1 && base_nos[bl - 1] == '/') {
            base_nos[bl - 1] = '\0';
            bl--;
        }
        if (bl > 0 && strncmp(path, base_nos, bl) == 0 && (path[bl] == '\0' || path[bl] == '/')) {
            path_start = path + bl;
            if (*path_start == '/') {
                path_start++;
            }
        } else {
            path_start = path;
        }
        free(base_nos);
    }
    base_path_len = strlen(base_path);
    (void)base_path_len;
    log_debug("search_dir: path is '%s', base_path is '%s', path_start is '%s'", path, base_path, path_start);

    scandir_baton.ig = ig;
    scandir_baton.base_path = base_path;
    scandir_baton.base_path_len = base_path_len;
    scandir_baton.path = path;
    scandir_baton.path_start = path_start;

    results = ag_scandir(path, &dir_list, &scandir_baton);
    if (results == 0) {
        log_debug("No results found in directory %s", path);
        goto search_dir_cleanup;
    } else if (results == -1) {
        if (errno == ENOTDIR) {
            /* Not a directory. Probably a file. */
            if (depth == 0 && opts.paths_len == 1) {
                /* If we're only searching one file, don't print the filename header at the top. */
                /* (handled during option parsing) */
            }
            search_file(path);
        } else {
            log_err("Error opening directory %s: %s", path, strerror(errno));
        }
        goto search_dir_cleanup;
    }

    for (i = 0; i < (size_t)results; i++) {
        dir = dir_list[i];
        int is_dir = 0;
        int is_lnk = 0;
        struct stat s;

        dir_full_path = ag_malloc(path_len + strlen(dir->d_name) + 2);
        sprintf(dir_full_path, "%s/%s", path, dir->d_name);

        if (dir->d_type == DT_LNK) {
            is_lnk = 1;
        }
        if (dir->d_type == DT_UNKNOWN || (is_lnk && opts.follow_symlinks)) {
            if (stat(dir_full_path, &s) != 0) {
                if (dir->d_type == DT_UNKNOWN) {
                    log_err("Skipping %s: Error fstat()ing file.", dir_full_path);
                } else {
                    log_err("Skipping %s: Error fstat()ing file.", dir_full_path);
                }
                free(dir_full_path);
                free(dir);
                continue;
            }
            is_dir = S_ISDIR(s.st_mode);
            if (opts.one_dev && s.st_dev != original_dev) {
                log_debug("File %s is on a different device. Skipping...", dir_full_path);
                free(dir_full_path);
                free(dir);
                continue;
            }
        } else {
            is_dir = (dir->d_type == DT_DIR);
        }

        if (is_dir) {
            if (opts.recurse_dirs) {
                if (depth < opts.depth || opts.depth < 0) {
                    log_debug("Searching dir %s", dir_full_path);
                    ignores *child_ig = init_ignore(ig, dir_full_path, strlen(dir_full_path));
                    /* abs path of the child relative to base */
                    {
                        char *rp = realpath(dir_full_path, NULL);
                        if (rp) {
                            size_t bl = strlen(base_path);
                            char *bn = ag_strdup(base_path);
                            if (bl > 1 && bn[bl - 1] == '/') {
                                bn[bl - 1] = '\0';
                                bl--;
                            }
                            free(child_ig->abs_path);
                            if (strncmp(rp, bn, bl) == 0 && rp[bl] == '/') {
                                child_ig->abs_path = ag_strdup(rp + bl + 1);
                            } else {
                                child_ig->abs_path = ag_strdup(rp);
                            }
                            child_ig->abs_path_len = strlen(child_ig->abs_path);
                            free(bn);
                            free(rp);
                        }
                    }
                    search_dir(child_ig, base_path, dir_full_path, depth + 1, original_dev);
                    cleanup_ignore(child_ig);
                } else {
                    log_debug("Skipping %s. Use the --depth option to search deeper.", dir_full_path);
                }
            }
            free(dir_full_path);
            free(dir);
            continue;
        }

        if (opts.file_search_regex) {
            int rc = pcre_exec(opts.file_search_regex, opts.file_search_regex_extra, dir_full_path,
                               strlen(dir_full_path), 0, 0, NULL, 0);
            if (rc < 0) {
                log_debug("Skipping %s due to file_search_regex.", dir_full_path);
                free(dir_full_path);
                free(dir);
                continue;
            } else if (opts.match_files) {
                log_debug("match_files: file_search_regex matched for %s.", dir_full_path);
                pthread_mutex_lock(&print_mtx);
                print_path(dir_full_path, opts.path_sep);
                pthread_mutex_unlock(&print_mtx);
                opts.match_found = 1;
                free(dir_full_path);
                free(dir);
                continue;
            }
        }

        {
            work_queue_t *queue_item = ag_malloc(sizeof(work_queue_t));
            queue_item->path = dir_full_path;
            queue_item->next = NULL;
            pthread_mutex_lock(&work_queue_mtx);
            if (work_queue_tail == NULL) {
                work_queue = queue_item;
            } else {
                work_queue_tail->next = queue_item;
            }
            work_queue_tail = queue_item;
            pthread_cond_signal(&files_ready);
            pthread_mutex_unlock(&work_queue_mtx);
            log_debug("%s added to work queue", dir_full_path);
        }
        free(dir);
    }

search_dir_cleanup:
    if (dir_list) {
        free(dir_list);
    }
    if (in_chain && chain_node) {
        current_chain = chain_node->parent;
        free(chain_node);
    }
}
EOF
echo ok"}

actions.command:
cd /workspace/src && cat > search.h <<'EOF'
#ifndef SEARCH_H
#define SEARCH_H

#include "ag.h"
#include "ignore.h"
#include "print.h"

typedef struct work_queue_t {
    char *path;
    struct work_queue_t *next;
} work_queue_t;

extern work_queue_t *work_queue;
extern work_queue_t *work_queue_tail;
extern int done_adding_files;
extern pthread_cond_t files_ready;
extern pthread_mutex_t work_queue_mtx;

size_t search_buf(const char *buf, const size_t buf_len, const char *dir_full_path, print_context_t *ctx);
void search_stream(FILE *stream, const char *path, int is_stdin);
void search_file(const char *file_full_path);
void *search_file_worker(void *i);
void search_dir(ignores *ig, const char *base_path, const char *path, const int depth, dev_t original_dev);

#endif
EOF
cat > search.c <<'EOF'
#include "search.h"
#include "zip.h"
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <dirent.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <limits.h>

work_queue_t *work_queue = NULL;
work_queue_t *work_queue_tail = NULL;
int done_adding_files = 0;
pthread_cond_t files_ready = PTHREAD_COND_INITIALIZER;
pthread_mutex_t work_queue_mtx = PTHREAD_MUTEX_INITIALIZER;

static int query_is_dot(void) {
    return !opts.literal && opts.query_len == 1 && opts.query[0] == '.';
}

static int word_boundary_ok(const char *buf, size_t buf_len, size_t start, size_t end) {
    int ok_start, ok_end;
    if (start == 0) {
        ok_start = 1;
    } else {
        ok_start = is_wordchar(buf[start - 1]) != is_wordchar(buf[start]);
    }
    if (end >= buf_len) {
        ok_end = 1;
    } else {
        ok_end = is_wordchar(buf[end - 1]) != is_wordchar(buf[end]);
    }
    return ok_start && ok_end;
}

typedef struct {
    match_t *matches;
    size_t len;
    size_t size;
    int stop;
} match_list_t;

static void add_match(match_list_t *ml, size_t start, size_t end, const char *path) {
    if (ml->len >= ml->size) {
        ml->size = ml->size ? ml->size * 2 : 100;
        ml->matches = ag_realloc(ml->matches, ml->size * sizeof(match_t));
    }
    ml->matches[ml->len].start = start;
    ml->matches[ml->len].end = end;
    ml->len++;
    if (opts.max_matches && ml->len >= opts.max_matches) {
        log_err("Too many matches in %s. Skipping the rest of this file.", path);
        ml->stop = 1;
    }
}

/* Find all matches in buf[region_start, region_end), appending to ml with
 * offsets relative to buf. */
static void find_matches(const char *buf, size_t region_start, size_t region_end, size_t buf_len,
                         const char *path, match_list_t *ml) {
    size_t buf_offset = region_start;
    int insensitive = (opts.casing == CASE_INSENSITIVE);

    if (opts.literal) {
        const char *match_ptr;
        const char *base = buf;
        while (buf_offset < region_end && !ml->stop) {
            match_ptr = literal_search(base + buf_offset, region_end - buf_offset, opts.query, opts.query_len, insensitive);
            if (match_ptr == NULL) {
                break;
            }
            {
                size_t start = (size_t)(match_ptr - base);
                size_t end = start + opts.query_len;
                if (opts.word_regexp && !word_boundary_ok(buf, buf_len, start, end)) {
                    buf_offset = start + 1;
                    continue;
                }
                log_debug("Match found. File %s, offset %lu bytes.", path, (unsigned long)start);
                add_match(ml, start, end, path);
                buf_offset = end;
                if (opts.query_len == 0) {
                    buf_offset++;
                }
            }
        }
    } else {
        int offset_vector[3];
        int rc;
        while (buf_offset < region_end && !ml->stop) {
            rc = pcre_exec(opts.re, opts.re_extra, buf, (int)region_end, (int)buf_offset, 0, offset_vector, 3);
            if (rc < 0) {
                break;
            }
            log_debug("Regex match found. File %s, offset %i bytes.", path, offset_vector[0]);
            buf_offset = offset_vector[1];
            if (offset_vector[0] == offset_vector[1]) {
                ++buf_offset;
                log_debug("Regex match is of length zero. Advancing offset one byte.");
            }
            add_match(ml, (size_t)offset_vector[0], (size_t)offset_vector[1], path);
        }
    }
}

size_t search_buf(const char *buf, const size_t buf_len, const char *dir_full_path, print_context_t *ctx) {
    int binary = -1;
    match_list_t ml;
    size_t matches_len = 0;
    int is_stdin = ctx->is_stdin;

    memset(&ml, 0, sizeof(ml));

    if (is_stdin) {
        binary = 0;
    } else if (!opts.search_binary_files) {
        binary = is_binary(buf, buf_len);
        if (binary) {
            log_debug("File %s is binary. Skipping...", dir_full_path);
            return 0;
        }
    }

    if (query_is_dot()) {
        /* match everything */
        if (buf_len > 0 || 1) {
            add_match(&ml, 0, buf_len, dir_full_path);
        }
    } else if (opts.multiline) {
        find_matches(buf, 0, buf_len, buf_len, dir_full_path, &ml);
    } else {
        /* search line by line */
        size_t line_start = 0;
        size_t i;
        for (i = 0; i <= buf_len && !ml.stop; i++) {
            if (i == buf_len || buf[i] == '\n') {
                find_matches(buf, line_start, i, buf_len, dir_full_path, &ml);
                line_start = i + 1;
            }
        }
    }
    matches_len = ml.len;

    if (opts.invert_match) {
        if (ml.matches == NULL) {
            ml.matches = ag_malloc(sizeof(match_t));
        }
        matches_len = invert_matches(buf, buf_len, ml.matches, matches_len);
    }

    if (opts.stats) {
        pthread_mutex_lock(&stats_mtx);
        stats.total_bytes += buf_len;
        stats.total_files++;
        stats.total_matches += matches_len;
        if (matches_len > 0) {
            stats.total_file_matches++;
        }
        pthread_mutex_unlock(&stats_mtx);
    }

    if (!opts.print_nonmatching_files && (matches_len > 0 || opts.print_all_paths)) {
        if (binary == -1 && !opts.print_filename_only) {
            binary = is_binary(buf, buf_len);
        }
        pthread_mutex_lock(&print_mtx);
        if (opts.print_count) {
            print_path_count(dir_full_path, opts.path_sep, matches_len);
        } else if (opts.print_filename_only) {
            print_path(dir_full_path, opts.path_sep);
        } else if (binary) {
            print_binary_file_matches(dir_full_path);
        } else {
            print_file_matches(ctx, dir_full_path, buf, buf_len, ml.matches, matches_len);
        }
        pthread_mutex_unlock(&print_mtx);
        opts.match_found = 1;
    } else if (is_stdin && opts.passthrough) {
        pthread_mutex_lock(&print_mtx);
        fwrite(buf, 1, buf_len, out_fd);
        pthread_mutex_unlock(&print_mtx);
    } else {
        log_debug("No match in %s", dir_full_path);
    }

    if (opts.print_nonmatching_files && matches_len == 0) {
        pthread_mutex_lock(&print_mtx);
        print_path(dir_full_path, opts.path_sep);
        pthread_mutex_unlock(&print_mtx);
        opts.match_found = 1;
    }

    free(ml.matches);
    return matches_len;
}

void search_stream(FILE *stream, const char *path, int is_stdin) {
    char *line = NULL;
    ssize_t line_len = 0;
    size_t line_cap = 0;
    size_t i;
    print_context_t ctx;

    print_context_init(&ctx, 1, is_stdin);

    for (i = 1; (line_len = getline(&line, &line_cap, stream)) > 0; i++) {
        size_t matches_len;
        size_t n = (size_t)line_len;
        size_t stripped = n;
        opts.stream_line_num = i;
        if (n > 0 && line[n - 1] == '\n') {
            stripped = n - 1;
        }
        if (is_stdin) {
            /* search the full line, print without the trailing newline */
            matches_len = search_buf_stream(line, n, stripped, path, &ctx);
            if (matches_len == 0) {
                pthread_mutex_lock(&print_mtx);
                print_trailing_context(&ctx, path, line, stripped);
                pthread_mutex_unlock(&print_mtx);
                print_context_append(&ctx, line, stripped);
            }
        } else {
            search_buf(line, n, path, &ctx);
            pthread_mutex_lock(&print_mtx);
            print_trailing_context(&ctx, path, line, stripped);
            pthread_mutex_unlock(&print_mtx);
        }
    }

    free(line);
    print_context_free(&ctx);
}

void search_file(const char *file_full_path) {
    int fd = -1;
    off_t f_len = 0;
    char *buf = NULL;
    struct stat statbuf;
    int rv = 0;
    FILE *fp = NULL;
    print_context_t ctx;

    rv = stat(file_full_path, &statbuf);
    if (rv != 0) {
        log_err("Skipping %s: Error fstat()ing file.", file_full_path);
        return;
    }

    fd = open(file_full_path, O_RDONLY);
    if (fd < 0) {
        log_err("Skipping %s: Error opening file: %s", file_full_path, strerror(errno));
        goto cleanup;
    }

    rv = fstat(fd, &statbuf);
    if (rv != 0) {
        log_err("Skipping %s: Error fstat()ing file.", file_full_path);
        goto cleanup;
    }

    if (S_ISFIFO(statbuf.st_mode)) {
        log_debug("%s is a named pipe. stream searching", file_full_path);
        fp = fdopen(fd, "r");
        search_stream(fp, file_full_path, 0);
        fclose(fp);
        fd = -1;
        goto cleanup;
    }

    if (!S_ISREG(statbuf.st_mode)) {
        log_err("Skipping %s: Mode %u is not a file.", file_full_path, statbuf.st_mode);
        goto cleanup;
    }

    f_len = statbuf.st_size;

    if (f_len == 0) {
        log_debug("Skipping %s: file is empty.", file_full_path);
        goto cleanup;
    }

    buf = ag_malloc((size_t)f_len + 1);
    {
        size_t total = 0;
        while (total < (size_t)f_len) {
            ssize_t r = read(fd, buf + total, (size_t)f_len - total);
            if (r < 0) {
                log_err("Skipping %s: Error reading file: %s", file_full_path, strerror(errno));
                goto cleanup;
            }
            if (r == 0) {
                break;
            }
            total += (size_t)r;
        }
        f_len = (off_t)total;
        buf[f_len] = '\0';
    }

    if (opts.search_zip_files) {
        ag_compression_type zip_type = is_zipped(buf, (size_t)f_len);
        if (zip_type != AG_NO_COMPRESSION) {
            size_t _buf_len = 0;
            char *_buf;
            log_debug("%s is a compressed file. stream searching", file_full_path);
            _buf = decompress(zip_type, buf, (size_t)f_len, file_full_path, &_buf_len);
            if (_buf == NULL || _buf_len == 0) {
                log_err("Cannot decompress zipped file %s", file_full_path);
                free(_buf);
                goto cleanup;
            }
            fp = fmemopen(_buf, _buf_len, "r");
            if (fp) {
                search_stream(fp, file_full_path, 0);
                fclose(fp);
            }
            free(_buf);
            goto cleanup;
        }
    }

    print_context_init(&ctx, 0, 0);
    search_buf(buf, (size_t)f_len, file_full_path, &ctx);
    print_context_free(&ctx);

cleanup:
    if (buf) {
        free(buf);
    }
    if (fd != -1) {
        close(fd);
    }
}

void *search_file_worker(void *i) {
    work_queue_t *queue_item;
    int worker_id = *(int *)i;

    log_debug("Worker %i started", worker_id);
    while (TRUE) {
        pthread_mutex_lock(&work_queue_mtx);
        while (work_queue == NULL) {
            if (done_adding_files) {
                pthread_mutex_unlock(&work_queue_mtx);
                log_debug("Worker %i finished.", worker_id);
                pthread_exit(NULL);
            }
            pthread_cond_wait(&files_ready, &work_queue_mtx);
        }
        queue_item = work_queue;
        work_queue = work_queue->next;
        if (work_queue == NULL) {
            work_queue_tail = NULL;
        }
        pthread_mutex_unlock(&work_queue_mtx);

        search_file(queue_item->path);
        free(queue_item->path);
        free(queue_item);
    }
    return NULL;
}

/* Check whether the directory `path` is one of the ancestors in the chain. */
typedef struct dir_chain {
    dev_t dev;
    ino_t ino;
    struct dir_chain *parent;
} dir_chain_t;

static __thread dir_chain_t *current_chain = NULL;

static int is_directory_loop(const char *path, dir_chain_t **out, struct stat *s) {
    dir_chain_t *c;
    if (stat(path, s) != 0) {
        return 0;
    }
    for (c = current_chain; c != NULL; c = c->parent) {
        if (c->dev == s->st_dev && c->ino == s->st_ino) {
            return 1;
        }
    }
    *out = ag_malloc(sizeof(dir_chain_t));
    (*out)->dev = s->st_dev;
    (*out)->ino = s->st_ino;
    (*out)->parent = current_chain;
    return 0;
}

static int ag_scandir(const char *dirname, struct dirent ***namelist, scandir_baton_t *baton) {
    DIR *dirp = NULL;
    struct dirent **names = NULL;
    struct dirent *entry, *d;
    int names_len = 32;
    int results_len = 0;

    dirp = opendir(dirname);
    if (dirp == NULL) {
        return -1;
    }

    names = ag_malloc(sizeof(struct dirent *) * names_len);

    while ((entry = readdir(dirp)) != NULL) {
        if (filename_filter(dirname, entry, baton) == 0) {
            continue;
        }
        if (results_len >= names_len) {
            names_len *= 2;
            names = ag_realloc(names, sizeof(struct dirent *) * names_len);
        }
        d = ag_malloc(sizeof(struct dirent));
        memcpy(d, entry, sizeof(struct dirent));
        names[results_len] = d;
        results_len++;
    }

    closedir(dirp);
    *namelist = names;
    return results_len;
}

void search_dir(ignores *ig, const char *base_path, const char *path, const int depth, dev_t original_dev) {
    struct dirent **dir_list = NULL;
    struct dirent *dir = NULL;
    scandir_baton_t scandir_baton;
    int results = 0;
    size_t base_path_len = 0;
    const char *path_start = path;
    const char **ignore_files;
    char *dir_full_path = NULL;
    size_t path_len = strlen(path);
    size_t i;
    dir_chain_t *chain_node = NULL;
    struct stat dir_stat;
    int in_chain = 0;

    /* The dir is in a loop if it resolves to one of its ancestors. */
    if (opts.follow_symlinks && depth > 0) {
        if (is_directory_loop(path, &chain_node, &dir_stat)) {
            log_err("Recursive directory loop: %s", path);
            return;
        }
    } else if (depth == 0) {
        if (stat(path, &dir_stat) == 0) {
            chain_node = ag_malloc(sizeof(dir_chain_t));
            chain_node->dev = dir_stat.st_dev;
            chain_node->ino = dir_stat.st_ino;
            chain_node->parent = current_chain;
        }
    } else {
        if (stat(path, &dir_stat) == 0) {
            chain_node = ag_malloc(sizeof(dir_chain_t));
            chain_node->dev = dir_stat.st_dev;
            chain_node->ino = dir_stat.st_ino;
            chain_node->parent = current_chain;
        }
    }
    if (chain_node) {
        current_chain = chain_node;
        in_chain = 1;
    }

    /* find agignore/gitignore/hgignore/etc files to load ignore patterns from */
    ignore_files = get_ignore_pattern_files();
    for (i = 0; ignore_files[i] != NULL; i++) {
        if (opts.skip_vcs_ignores && i > 0) {
            break;
        }
        dir_full_path = ag_malloc(path_len + strlen(ignore_files[i]) + 2);
        sprintf(dir_full_path, "%s/%s", path, ignore_files[i]);
        load_ignore_patterns(ig, dir_full_path);
        free(dir_full_path);
        dir_full_path = NULL;
    }

    /* path_start: path relative to the base */
    {
        char *base_nos = ag_strdup(base_path);
        size_t bl = strlen(base_nos);
        if (bl > 1 && base_nos[bl - 1] == '/') {
            base_nos[bl - 1] = '\0';
            bl--;
        }
        if (bl > 0 && strncmp(path, base_nos, bl) == 0 && (path[bl] == '\0' || path[bl] == '/')) {
            path_start = path + bl;
            if (*path_start == '/') {
                path_start++;
            }
        } else {
            path_start = path;
        }
        free(base_nos);
    }
    base_path_len = strlen(base_path);
    (void)base_path_len;
    log_debug("search_dir: path is '%s', base_path is '%s', path_start is '%s'", path, base_path, path_start);

    scandir_baton.ig = ig;
    scandir_baton.base_path = base_path;
    scandir_baton.base_path_len = base_path_len;
    scandir_baton.path = path;
    scandir_baton.path_start = path_start;

    results = ag_scandir(path, &dir_list, &scandir_baton);
    if (results == 0) {
        log_debug("No results found in directory %s", path);
        goto search_dir_cleanup;
    } else if (results == -1) {
        if (errno == ENOTDIR) {
            /* Not a directory. Probably a file. */
            if (depth == 0 && opts.paths_len == 1) {
                /* If we're only searching one file, don't print the filename header at the top. */
                /* (handled during option parsing) */
            }
            search_file(path);
        } else {
            log_err("Error opening directory %s: %s", path, strerror(errno));
        }
        goto search_dir_cleanup;
    }

    for (i = 0; i < (size_t)results; i++) {
        dir = dir_list[i];
        int is_dir = 0;
        int is_lnk = 0;
        struct stat s;

        dir_full_path = ag_malloc(path_len + strlen(dir->d_name) + 2);
        sprintf(dir_full_path, "%s/%s", path, dir->d_name);

        if (dir->d_type == DT_LNK) {
            is_lnk = 1;
        }
        if (dir->d_type == DT_UNKNOWN || (is_lnk && opts.follow_symlinks)) {
            if (stat(dir_full_path, &s) != 0) {
                if (dir->d_type == DT_UNKNOWN) {
                    log_err("Skipping %s: Error fstat()ing file.", dir_full_path);
                } else {
                    log_err("Skipping %s: Error fstat()ing file.", dir_full_path);
                }
                free(dir_full_path);
                free(dir);
                continue;
            }
            is_dir = S_ISDIR(s.st_mode);
            if (opts.one_dev && s.st_dev != original_dev) {
                log_debug("File %s is on a different device. Skipping...", dir_full_path);
                free(dir_full_path);
                free(dir);
                continue;
            }
        } else {
            is_dir = (dir->d_type == DT_DIR);
        }

        if (is_dir) {
            if (opts.recurse_dirs) {
                if (depth < opts.depth || opts.depth < 0) {
                    log_debug("Searching dir %s", dir_full_path);
                    ignores *child_ig = init_ignore(ig, dir_full_path, strlen(dir_full_path));
                    /* abs path of the child relative to base */
                    {
                        char *rp = realpath(dir_full_path, NULL);
                        if (rp) {
                            size_t bl = strlen(base_path);
                            char *bn = ag_strdup(base_path);
                            if (bl > 1 && bn[bl - 1] == '/') {
                                bn[bl - 1] = '\0';
                                bl--;
                            }
                            free(child_ig->abs_path);
                            if (strncmp(rp, bn, bl) == 0 && rp[bl] == '/') {
                                child_ig->abs_path = ag_strdup(rp + bl + 1);
                            } else {
                                child_ig->abs_path = ag_strdup(rp);
                            }
                            child_ig->abs_path_len = strlen(child_ig->abs_path);
                            free(bn);
                            free(rp);
                        }
                    }
                    search_dir(child_ig, base_path, dir_full_path, depth + 1, original_dev);
                    cleanup_ignore(child_ig);
                } else {
                    log_debug("Skipping %s. Use the --depth option to search deeper.", dir_full_path);
                }
            }
            free(dir_full_path);
            free(dir);
            continue;
        }

        if (opts.file_search_regex) {
            int rc = pcre_exec(opts.file_search_regex, opts.file_search_regex_extra, dir_full_path,
                               strlen(dir_full_path), 0, 0, NULL, 0);
            if (rc < 0) {
                log_debug("Skipping %s due to file_search_regex.", dir_full_path);
                free(dir_full_path);
                free(dir);
                continue;
            } else if (opts.match_files) {
                log_debug("match_files: file_search_regex matched for %s.", dir_full_path);
                pthread_mutex_lock(&print_mtx);
                print_path(dir_full_path, opts.path_sep);
                pthread_mutex_unlock(&print_mtx);
                opts.match_found = 1;
                free(dir_full_path);
                free(dir);
                continue;
            }
        }

        {
            work_queue_t *queue_item = ag_malloc(sizeof(work_queue_t));
            queue_item->path = dir_full_path;
            queue_item->next = NULL;
            pthread_mutex_lock(&work_queue_mtx);
            if (work_queue_tail == NULL) {
                work_queue = queue_item;
            } else {
                work_queue_tail->next = queue_item;
            }
            work_queue_tail = queue_item;
            pthread_cond_signal(&files_ready);
            pthread_mutex_unlock(&work_queue_mtx);
            log_debug("%s added to work queue", dir_full_path);
        }
        free(dir);
    }

search_dir_cleanup:
    if (dir_list) {
        free(dir_list);
    }
    if (in_chain && chain_node) {
        current_chain = chain_node->parent;
        free(chain_node);
    }
}
