static int default_worker_count(void) {
    long num_cores = sysconf(_SC_NPROCESSORS_ONLN);
    int workers;
    if (num_cores < 1) {
        num_cores = 1;
    }
    workers = num_cores < 8 ? (int)num_cores : 8;
    if (opts.literal) {
        workers--;
    }
    if (workers < 1) {
        workers = 1;
    }
    return workers;
}

